  check('内置配色都能通过校验', BUILTIN_THEMES.every((t) => normalizeThemeColors(t.colors) !== null))
  check('每套主题至少有 4 个分支配色', BUILTIN_THEMES.every((t) => t.colors.branches.length >= 4))
