const DOC_A = 'file:d:\\a.xmind'
const DOC_B = 'file:d:\\b.xmind'

function snap(over: Partial<SnapshotItem> & { id: string }): SnapshotItem {
  return {
    docKey: DOC_A,
    title: '甲',
    path: 'D:\\a.xmind',
    at: 1000,
    size: 2048,
    reason: 'auto',
    hash: `hash-${over.id}`,
    ...over
  }
}

function testSnapshots(): void {
  group('版本快照：文档键')

