  check('空白路径也返回 null', documentKeyOf('   ') === null)
  check('undefined 返回 null', documentKeyOf(undefined) === null)
  check('首尾空格不影响归并', documentKeyOf('  D:\\a.xmind  ') === documentKeyOf('D:\\a.xmind'))

  group('版本快照：索引校验')

  eq('空索引没有条目', emptySnapshotIndex().items.length, 0)
