  })
  eq('缺字段的条目被丢弃', orphaned.index.items.length, 0)
  eq('丢弃的条目会上报要删的文件（不安全的 id 除外）', orphaned.dropped, ['orphan1'])

  const duplicated = normalizeSnapshotIndex({
    items: [
