    console.log(`全部通过：${passed} 项断言`)
  } else {
    console.log(`通过 ${passed} 项，失败 ${failures.length} 项：`)
    for (const item of failures) console.log(`  - ${item}`)
    process.exitCode = 1
  }
}

main().catch((error) => {
  console.error('\n自检异常中断：', error)
  process.exitCode = 1
})

