/**
 * 把设置里的默认值送到渲染层并让测量缓存失效。
 * 对齐是段落级的兜底默认值（见 render/defaults.ts），改了必须重算测量。
 */
function applyRenderDefaults(settings: AppSettings): void {
  setDefaultTextAlign(settings.defaultAlign)
  // 代码块基准字号：布局测量 / 画布 / 导出共用（改了必须重算测量）
  setCodeFontSizeBase(settings.defaultCodeFontSize)
  bumpMeasureEpoch()
  // 光让缓存失效还不够：布局自身也要重跑，否则改了设置要等别的操作才生效
  useEditor.getState().bumpRenderEpoch()
}

function fileNameOf(path: string | null): string | null {
  if (!path) return null
  const parts = path.split(/[\\/]/)
  return parts[parts.length - 1] || path
}

interface PastedImage {
  path: string
  width: number
  height: number
}

/**
 * 读取系统剪贴板里的图片。
 *
 * 优先走渲染进程的标准异步剪贴板 API（navigator.clipboard.read）——它读的就是
 * 系统剪贴板，截图 / 复制的图都能拿到；读不到（权限或实现差异）再退回
 * 主进程的 paste-image。两条路都没有图片就返回 null，由调用方按「粘贴节点」处理。
 */
async function readClipboardImage(): Promise<PastedImage | null> {
  try {
    const items = await navigator.clipboard.read()
    for (const item of items) {
      const mime = item.types.find((type) => type.startsWith('image/'))
      if (!mime) continue
      const blob = await item.getType(mime)
      const bytes = new Uint8Array(await blob.arrayBuffer())
      if (bytes.byteLength === 0) continue
      const picked = await window.api.addImage(
        activeDocId(),
        mime === 'image/jpeg' ? '剪贴板图片.jpg' : '剪贴板图片.png',
        bytes
      )
      if (picked) return { path: picked.path, width: picked.width, height: picked.height }
    }
  } catch {
    /* 渲染进程读不到就走主进程 */
  }
  try {
    const picked = await window.api.pasteImage(activeDocId())
    return picked ? { path: picked.path, width: picked.width, height: picked.height } : null
  } catch {
    return null
  }
}

export default function App(): ReactElement {
  const filePath = useEditor((s) => s.filePath)
  const dirty = useEditor((s) => s.dirty)
  // 只订阅「中心主题的文字」这一个字符串：标题栏与默认文件名都跟着它变，又不至于每次改动都重渲染
  const rootTitle = useEditor((s) => activeRoot(s.workbook).title)
  // 工具栏收纳状态：右键「收进更多 ▾」后要立即反映到快捷栏与「更多」菜单
  const toolbarHidden = useEditor((s) => s.appSettings.toolbarHidden)

  const [toast, setToast] = useState<string | null>(null)
  const [recovery, setRecovery] = useState<RecoveryInfo | null>(null)
  /** 未保存确认：run＝确认后的动作；fileName＝被确认的文档名；discard＝「不保存」的额外动作 */
  const [pending, setPending] = useState<{
    run: () => void
    fileName: string
    discard?: () => void
  } | null>(null)
  const [showShortcuts, setShowShortcuts] = useState(false)
  /** 右侧抽屉：同一时刻只开一个 */
  const [sidePanel, setSidePanel] = useState<'none' | 'theme' | 'node' | 'search'>('none')
  /** 左侧大纲面板：与画布并排显示，改哪边另一边都跟着变 */
  const [showOutline, setShowOutline] = useState(false)
  /** 导出设置框 */
  const [showExport, setShowExport] = useState(false)
  /** AI 对话框：生成 / 扩写 / 润色 */
  const [aiTask, setAiTask] = useState<AiTask | null>(null)
  const [showAiSettings, setShowAiSettings] = useState(false)
  const themesRef = useRef<ThemeDefinition[]>([])
  /** 历史记录 / 常用 / 保存位置 */
  const [showHistory, setShowHistory] = useState(false)
  const toastTimer = useRef<number | null>(null)
  /** 是否还停在「发现未保存内容」这一步没做决定 */
  const recoveryPendingRef = useRef(false)

  const showToast = useCallback((message: string): void => {
    setToast(message)
    if (toastTimer.current !== null) window.clearTimeout(toastTimer.current)
    toastTimer.current = window.setTimeout(() => setToast(null), 4600)
  }, [])

  /* ------------------------------------------------------------------ */
  /* 文件操作                                                            */
  /* ------------------------------------------------------------------ */

  /**
   * 先把「正在编辑但还没提交」的文本落定。
   * 否则 dirty 判断与实际内容不一致，会出现「刚打的字被无声丢掉」。
   */
  const commitPending = useCallback((): void => {
    const store = useEditor.getState()
    if (store.editingId) store.commitEdit()
  }, [])

  const saveDocument = useCallback(
    async (forceSaveAs = false): Promise<boolean> => {
      commitPending()
      const state = useEditor.getState()
      try {
        if (!state.filePath || forceSaveAs) {
          // 默认文件名用中心主题的名字（空标题才退回「未命名导图」）
          const suggested = state.filePath ?? defaultFileName(state.workbook, 'xmind')
          const result = await window.api.saveAs(activeDocId(), state.workbook, suggested)
          if (!result) return false
          useEditor.getState().markSaved(result.path)
          showToast(`已保存到 ${result.path}`)
        } else {
          await window.api.saveToPath(activeDocId(), state.filePath, state.workbook)
          useEditor.getState().markSaved(state.filePath)
          showToast('已保存')
        }
        await window.api.clearAutosave()
        return true
      } catch (err) {
        showToast(`保存失败：${(err as Error).message}`)
        return false
      }
    },
    [commitPending, showToast]
  )

  /** 把「打开结果」落成**一个标签**（对话框打开与历史记录打开共用一套收尾逻辑） */
  const openIntoTab = useCallback(
    async (result: OpenResult): Promise<void> => {
      const tabs = useTabs.getState()
      // 已经开着这个文件：直接切过去（多标签去重，不会同一文件开两份）
      if (!result.copy) {
        const existing = tabs.findByPath(result.path)
        if (existing) {
          tabs.switchTo(existing)
          showToast('这个文件已经开着，已帮你切换到那个标签')
          return
        }
      }
      // 副本没有磁盘归属：当成未保存的新文档（保存时会提示另存为），
      // 这样它跟原文档完全独立——导入/导出/保存都不会影响另一个画布
      tabs.openWorkbook(result.workbook, result.copy ? null : result.path)
      const messages: string[] = []
      if (result.resourceCount > 0) {
        messages.push(`已加载 ${result.resourceCount} 个图片/附件资源（保存时会一并写回）`)
      }
      if (result.warnings.length > 0) messages.push(...result.warnings)
      if (messages.length > 0) showToast(messages.join('；'))
    },
    [showToast]
  )

  const openDocument = useCallback(async (): Promise<void> => {
    commitPending()
    try {
      const result = await window.api.openDialog(activeDocId())
      if (!result) return
      await openIntoTab(result)
    } catch (err) {
      showToast(`打开失败：${(err as Error).message}`)
    }
  }, [commitPending, openIntoTab, showToast])

  /** 直接打开某个路径（历史记录里点一条、外部拖入/双击共用） */
  const openPath = useCallback(
    async (path: string): Promise<void> => {
      commitPending()
      try {
        await openIntoTab(await window.api.openPath(activeDocId(), path))
      } catch (err) {
        showToast(`打开失败：${(err as Error).message}`)
      }
    },
    [commitPending, openIntoTab, showToast]
  )

  /** 直接打开某个路径（历史记录里点一条走这里） */

  /**
   * 恢复到某个历史版本。
   *
   * 恢复前**先自动存一份「恢复前」的版本**：万一点错了还能再回来，
   * 这也是恢复动作不进撤销栈的安全网。
   */
  const restoreSnapshot = useCallback(
    async (snapshotId: string): Promise<void> => {
      commitPending()
      const store = useEditor.getState()

      try {
        await window.api.snapshotCreate(activeDocId(), {
          workbook: snapshotForSave(store),
          path: store.filePath,
          title: defaultDocumentName(store.workbook),
          reason: 'before-restore'
        })
      } catch {
        // 兜底版本存不上也要继续恢复，不能因此卡住用户
      }

      try {
        const result = await window.api.snapshotRestore(activeDocId(), snapshotId)
        useEditor.getState().restoreDocument(result.workbook)
        const messages = ['已恢复到所选版本（恢复前的状态也留了一份，可再切回）']
        if (result.resourceCount > 0) messages.push(`带回了 ${result.resourceCount} 个图片/附件资源`)
        if (result.warnings.length > 0) messages.push(...result.warnings)
        showToast(messages.join('；'))
      } catch (error) {
        showToast(`恢复失败：${(error as Error).message}`)
      }
    },
    [commitPending, showToast]
  )

  /**
   * 正常关闭应用。
   * 关键：关闭前必须清掉自动存档，否则「不保存退出」后下次启动还会反复提示恢复。
   * 但如果用户还停在「发现未保存内容」的弹窗上没有做决定，就不能悄悄删掉存档。
   */
  const closeApp = useCallback((): void => {
    const finish = (): void => window.api.confirmClose()
    if (recoveryPendingRef.current) {
      finish()
      return
    }
    void (async () => {
      try {
        await window.api.clearAutosave()
      } catch {
        /* 忽略：清不掉也不该阻塞关闭 */
      }
      finish()
    })()
  }, [])

  /**
   * 按 id 找主题。**内置表也要查**：
   * `themesList()` 返回的只有自定义主题，如果只查它，
   * 用户把内置主题设为默认时会静默失效——这正是「默认主题设置无效」的根因。
   */
  const resolveTheme = useCallback((id: string | null): ThemeDefinition | null => {
    if (!id) return null
    return (
      BUILTIN_THEMES.find((item) => item.id === id) ??
      themesRef.current.find((item) => item.id === id) ??
      null
    )
  }, [])

  /* 启动时读一次应用设置与主题库：默认参数影响新建文档、主题下拉可选项 */
  useEffect(() => {
    void (async () => {
      try {
        const loaded = await window.api.settingsLoad()
        useEditor.getState().setAppSettings(loaded)
        applyRenderDefaults(loaded)
      } catch {
        /* 读不到就用内置默认值 */
      }
      try {
        themesRef.current = await window.api.themesList()
      } catch {
        themesRef.current = []
      }
      // 启动这一份空白文档也按「默认主题」起手。
      // 必须等主题库读完再套，否则自定义主题还查不到。
      const theme = resolveTheme(useEditor.getState().appSettings.defaultThemeId)
      if (theme) useEditor.getState().primeTheme(theme)
    })()
  }, [resolveTheme])

  /**
   * 改「默认对齐 / 默认字体」这类渲染兜底值后，让测量缓存失效。
   * 设置值本身的写入与落盘统一走 `patchAppSettings`（各面板各自调用）。
   */
  const handleRenderDefaults = useCallback((next: AppSettings): void => {
    applyRenderDefaults(next)
  }, [])

  /** 「默认样式」改动后的统一收尾：渲染兜底值失效 */
  const onDefaultStyleChanged = useCallback((): void => {
    applyRenderDefaults(useEditor.getState().appSettings)
  }, [])

  /** 主题面板：把某个主题设为新文档的默认主题 */
  const handleSetDefaultTheme = useCallback(
    (themeId: string): void => {
      void patchAppSettings({ defaultThemeId: themeId }).then((next) => {
        applyRenderDefaults(next)
        showToast('已设为新文档的默认主题')
      })
    },
    [showToast]
  )

  const newDocument = useCallback((): void => {
    commitPending()
    // 新建＝开一个**新标签**：当前文档原样留在自己的标签里，不需要未保存确认
    useTabs.getState().newTab()
    // 新文档按「设置」里的默认主题起手（打开已有文件不动它自己的主题）。
    // 用 primeTheme 而不是 applyTheme：后者会写撤销历史并把新文档标成未保存。
    const theme = resolveTheme(useEditor.getState().appSettings.defaultThemeId)
    if (theme) useEditor.getState().primeTheme(theme)
  }, [commitPending, resolveTheme])

  /** 关闭一个标签（带未保存确认；确认文案里显示这份文档自己的名字） */
  const closeTabById = useCallback(
    (id: string): void => {
      commitPending()
      const tabs = useTabs.getState()
      const tab = tabs.tabs.find((item) => item.id === id)
      if (!tab) return
      const liveDirty = id === tabs.activeId ? useEditor.getState().dirty : tab.dirty
      const run = (): void => {
        useTabs.getState().closeTab(id)
        // 主进程丢掉这份文档的图片/附件资源（别的标签不受影响）
        void window.api.releaseDoc(id).catch(() => undefined)
      }
      if (liveDirty) {
        // 保存要保的是被关的那份：先把它切到前台再问
        if (id !== tabs.activeId) useTabs.getState().switchTo(id)
        setPending({ fileName: tabTitleOf(tab), run, discard: run })
        return
      }
      run()
    },
    [commitPending]
  )

  /** 有未保存内容时先弹确认框（先把未提交的输入落定，dirty 才准确） */
  const guard = useCallback(
    (run: () => void): void => {
      commitPending()
      if (useEditor.getState().dirty) {
        const state = useEditor.getState()
        const active = useTabs.getState().tabs.find((item) => item.id === useTabs.getState().activeId)
        setPending({ fileName: active ? tabTitleOf(active) : '当前文档', run })
      } else run()
    },
    [commitPending]
  )

  /* ------------------------------------------------------------------ */
  /* 多窗口（一个窗口 = 一份文档）                                        */
  /* ------------------------------------------------------------------ */

  /**
   * 开一个**新窗口**（一份新文档）。
   * 不需要未保存确认：新窗口是空的，不动当前文档。
   */
  const openNewWindow = useCallback((): void => {
    void window.api.newWindow()
  }, [])

  /**
   * 在**新窗口打开当前画布**（实际是这份文档的**副本**）。
   *
   * 副本完全独立：没有磁盘归属，导入/导出/保存都走自己的路，
   * **不会影响当前文档**——这就是"A 画布新建 B 画布、两者互不影响"的做法。
   * 因为副本是直接从内存里的文档序列化出来的（含未保存改动），不需要先保存。
   */
  const openCopyWindow = useCallback((): void => {
    commitPending()
    const store = useEditor.getState()
    void (async () => {
      const result = await window.api.openWorkbookInNewWindow(activeDocId(), store.workbook)
      showToast(
        result === 'ok'
          ? '已在新窗口打开副本：两边互不影响，保存时会让你另存为新文件'
          : '新窗口打开失败，请重试'
      )
    })()
  }, [commitPending, showToast])

  /**
   * AI「生成新导图」：在**新窗口**里成为一份独立文档（副本语义）。
   * 不往当前文档里塞内容——那会让用户觉得"当前导图被塞了东西"。
   */
  const openGeneratedInNewWindow = useCallback(
    (root: OutlineNode, title: string): void => {
      const workbook = createWorkbookFromRoot(outlineToTopic(root), title || 'AI 导图')
      void (async () => {
        const opened = await window.api.openWorkbookInNewWindow(activeDocId(), workbook)
        showToast(opened === 'ok' ? '已在新窗口生成一份独立导图' : '新窗口打开失败，请重试')
      })()
    },
    [showToast]
  )

  /* ------------------------------------------------------------------ */
  /* 导入 / 导出（工具栏与菜单共用）                                      */
  /* ------------------------------------------------------------------ */

  /** 导入主题文件（.json），存进「我的主题」 */
  const importTheme = useCallback(async (): Promise<void> => {
    try {
      const theme = await window.api.themesImport()
      if (!theme) return
      await window.api.themesSave(theme)
      showToast(`已导入主题「${theme.name}」，可在「主题外观」里选用`)
    } catch (error) {
      showToast(`导入主题失败：${(error as Error).message}`)
    }
  }, [showToast])

  /** 导出当前画布的大纲（TXT / Markdown / OPML） */
  const exportOutlineAs = useCallback(
    async (format: OutlineFormat): Promise<void> => {
      commitPending()
      try {
        const workbook = useEditor.getState().workbook
        const path = await window.api.exportOutline(workbook, format)
        if (path) showToast(`已导出大纲：${path}`)
      } catch (error) {
        showToast(`导出大纲失败：${(error as Error).message}`)
      }
    },
    [commitPending, showToast]
  )

  /**
   * 导入 Markdown / OPML 一键生成导图。
   * 解析逻辑在 shared 里（纯函数、有自检），这里只负责选文件、落地到新画布、给提示。
   */
  const importOutlineFile = useCallback(
    async (kind: 'markdown' | 'opml'): Promise<void> => {
      commitPending()
      try {
        const file = await window.api.importText(kind)
        if (!file) return

        const fallbackTitle = file.name.replace(/\.[^.]+$/, '') || '导入的大纲'
        const parsed =
          kind === 'markdown'
            ? parseMarkdownOutline(file.text, fallbackTitle)
            : parseOpmlOutline(file.text, fallbackTitle)

        if (!parsed.root) {
          showToast(`导入失败：${parsed.warnings.join('；') || '文件里没有可用的大纲'}`)
          return
        }

        // 导入＝在**新窗口**里成为一份独立文档：不往当前文档里塞内容，
        // 也就不会影响用户正在编辑的东西（保存时另存为新文件）
        const workbook = createWorkbookFromRoot(outlineToTopic(parsed.root), fallbackTitle)
        const opened = await window.api.openWorkbookInNewWindow(activeDocId(), workbook)
        const extra = parsed.warnings.length > 0 ? `（${parsed.warnings.join('；')}）` : ''
        showToast(
          opened === 'ok'
            ? `已在新窗口打开「${file.name}」导入的 ${parsed.count} 个主题${extra}`
            : '导入失败：新窗口没能打开'
        )
      } catch (error) {
        showToast(`导入失败：${(error as Error).message}`)
      }
    },
    [commitPending, showToast]
  )

  /* ------------------------------------------------------------------ */
  /* 菜单命令                                                            */
  /* ------------------------------------------------------------------ */

  useEffect(() => {
    const off = window.api.onMenuCommand((command) => {
      const store = useEditor.getState()
      switch (command) {
        case 'file:new':
          // 新标签不动当前文档，不需要未保存确认
          newDocument()
          break
        case 'file:open':
          void openDocument()
          break
        case 'file:save':
          void saveDocument(false)
          break
        case 'file:save-as':
          void saveDocument(true)
          break
        case 'file:open-sheet-window':
          openCopyWindow()
          break
        case 'edit:undo':
          store.undo()
          break
        case 'edit:redo':
          store.redo()
          break
        case 'edit:delete':
          store.deleteSelection()
          break
        case 'edit:copy':
          store.copySelection()
          break
        case 'edit:paste':
          store.paste()
          break
        case 'view:zoom-in':
          viewportActions.zoomTo(store.zoom * 1.2)
          break
        case 'view:zoom-out':
          viewportActions.zoomTo(store.zoom / 1.2)
          break
        case 'view:zoom-reset':
          viewportActions.zoomTo(1)
          break
        case 'view:fit':
          viewportActions.fit()
          break
        case 'view:lock':
          // 视角锁定：开着的时候视角始终把选中的主题按在视口正中
          showToast(
            store.toggleViewLock() ? '视角锁定：已开启，视角会跟住选中的主题' : '视角锁定：已关闭'
          )
          break
        case 'help:shortcuts':
          setShowShortcuts(true)
          break
        case 'file:import-theme':
          void importTheme()
          break
        case 'file:import-markdown':
          void importOutlineFile('markdown')
          break
        case 'file:import-opml':
          void importOutlineFile('opml')
          break
        case 'file:export-image':
          setShowExport(true)
          break
        case 'file:export-txt':
          void exportOutlineAs('txt')
          break
        case 'file:export-md':
          void exportOutlineAs('md')
          break
        case 'file:export-opml':
          void exportOutlineAs('opml')
          break
        case 'file:history':
          setShowHistory(true)
          break
        default:
          break
      }
    })
    return off
  }, [
    guard,
    newDocument,
    openDocument,
    saveDocument,
    importTheme,
    importOutlineFile,
    exportOutlineAs,
    openCopyWindow,
    showToast
  ])

  /**
   * 从文件管理器打开本地文档。
   *
   * - **启动时**（双击 `.xmind` / 把文件拖到 exe 上 / 右键「打开方式 → SMind」）：路径在命令行里，
   *   主进程替我们存着，这里就绪后取一次（取走即清空）；
   * - **窗口已经开着时**再打开一个：主进程通过 `fileOpenRequest` 推过来。
   *
   * 标签为主：已经开着就切到那个标签，否则开**新标签**——都不动当前文档，无需未保存确认。
   */
  const receiveExternalFile = useCallback(
    (path: string): void => {
      const tabs = useTabs.getState()
      const existing = tabs.findByPath(path)
      if (existing) {
        tabs.switchTo(existing)
        showToast('这个文件已经开着，已帮你切换到那个标签')
        return
      }
      void openPath(path)
    },
    [openPath, showToast]
  )

  useEffect(() => {
    void (async () => {
      const path = await window.api.openFilePending()
      if (!path) return
      void openPath(path)
    })()
    return window.api.onFileOpenRequest((path) => receiveExternalFile(path))
  }, [openPath, receiveExternalFile])

  /* ------------------------------------------------------------------ */
  /* 关闭窗口                                                            */
  /* ------------------------------------------------------------------ */

  /**
   * 退出前把**每个有未保存改动的标签**都问一遍（逐个切到前台询问），
   * 全部有了着落（保存 / 丢弃）才真正关闭窗口。
   */
  const forceCloseIds = useRef(new Set<string>())
  const closeWindowFlow = useCallback((): void => {
    commitPending()
    const tabs = useTabs.getState()
    const askThis = (fileName: string): void =>
      setPending({
        fileName,
        run: closeWindowFlow,
        discard: () => {
          forceCloseIds.current.add(useTabs.getState().activeId)
          closeWindowFlow()
        }
      })
    // 先问激活的（它就是屏幕上这份，用户最有概念）
    if (useEditor.getState().dirty && !forceCloseIds.current.has(tabs.activeId)) {
      const active = tabs.tabs.find((item) => item.id === tabs.activeId)
      askThis(active ? tabTitleOf(active) : '当前文档')
      return
    }
    // 再问其余脏标签（逐个切过去问）
    const nextDirty = tabs.tabs.find(
      (item) => item.dirty && item.id !== tabs.activeId && !forceCloseIds.current.has(item.id)
    )
    if (nextDirty) {
      tabs.switchTo(nextDirty.id)
      askThis(tabTitleOf(nextDirty))
      return
    }
    closeApp()
  }, [commitPending])

  useEffect(() => {
    const off = window.api.onCloseRequest(() => {
      forceCloseIds.current.clear()
      closeWindowFlow()
    })
    return off
  }, [closeWindowFlow])

  /* ------------------------------------------------------------------ */
  /* 自动保存                                                            */
  /* ------------------------------------------------------------------ */

  useEffect(() => {
    const timer = window.setInterval(() => {
      const store = useEditor.getState()
      if (!store.dirty) return
      // 用快照而不是直接落库：把正在输入但还没提交的文本也写进去，
      // 同时不打断用户的输入（不会退出编辑态）
      void window.api
        .autosave(
          activeDocId(),
          snapshotForSave(store),
          store.filePath,
          fileNameOf(store.filePath) ?? '未命名导图'
        )
        .catch((error: unknown) => {
          // 自动保存失败必须让用户知道：最坏的情况不是"存不上"，
          // 而是用户以为存上了、其实没有
          const detail = error instanceof Error ? error.message : String(error)
          showToast(`自动保存失败：${detail}（请尽快手动保存一次）`)
        })
    }, 30000)
    return () => window.clearInterval(timer)
  }, [showToast])

  /* ------------------------------------------------------------------ */
  /* 自动版本快照                                                        */
  /* ------------------------------------------------------------------ */

  useEffect(() => {
    // 每 10 分钟留一个版本；内容与上一份相同（或距上次太近）时
    // 主进程会按内容指纹直接忽略，不会白写盘。
    // 只对「已保存过的文档」记录：还没有路径的文档由自动保存与崩溃恢复兜底。
    const timer = window.setInterval(() => {
      const store = useEditor.getState()
      if (!store.filePath) return
      void window.api
        .snapshotCreate(activeDocId(), {
          workbook: snapshotForSave(store),
          path: store.filePath,
          title: defaultDocumentName(store.workbook),
          reason: 'auto'
        })
        .catch(() => undefined)
    }, 600000)
    return () => window.clearInterval(timer)
  }, [])

  /* ------------------------------------------------------------------ */
  /* 崩溃恢复                                                            */
  /* ------------------------------------------------------------------ */

  useEffect(() => {
    void (async () => {
      try {
        const info = await window.api.recoveryCheck()
        if (info) {
          recoveryPendingRef.current = true
          setRecovery(info)
        }
      } catch {
        /* 忽略 */
      }
    })()
  }, [])

  const handleRestore = useCallback(async (): Promise<void> => {
    setRecovery(null)
    try {
      const result = await window.api.recoveryLoad(activeDocId())
      if (result) {
        useTabs.getState().openWorkbook(result.workbook, result.path || null)
        showToast('已恢复未保存的内容')
      }
    } catch (err) {
      // 存档读不出来（多半已损坏），清掉它，否则每次启动都会再问一次
      void window.api.recoveryDiscard()
      showToast(`恢复失败：${(err as Error).message}`)
    } finally {
      recoveryPendingRef.current = false
    }
  }, [showToast])

  const handleDiscardRecovery = useCallback((): void => {
    recoveryPendingRef.current = false
    setRecovery(null)
    void window.api.recoveryDiscard()
  }, [])

  /* ------------------------------------------------------------------ */
  /* 窗口标题                                                            */
  /* ------------------------------------------------------------------ */

  useEffect(() => {
    // 未保存过的新文件，标题也用中心主题的名字，和保存时的默认文件名保持一致
    const name = filePath
      ? (fileNameOf(filePath) ?? '未命名导图')
      : defaultDocumentName(useEditor.getState().workbook)
    window.api.setTitle(`${dirty ? '● ' : ''}${name} - SMind`)
    // 告诉主进程「这个标签开着哪个文件」：多标签/多窗口下双击同一个 .xmind 时，
    // 主进程会聚焦对应窗口，由渲染层切到那个标签（同一文件开两份会互相覆盖）
    window.api.reportDocument(activeDocId(), filePath)
    // rootTitle 参与依赖：改名后标题栏要立刻跟着变
  }, [filePath, dirty, rootTitle])

  /**
   * 画布上选中了画布元素（概要 / 边界 / 关系线）时把节点属性面板打开：
   * 它们的文字、字体、删除入口都在面板里，选中了却不给看，用户会以为"选中没生效"。
   */
  const nodePanelTick = useEditor((state) => state.nodePanelTick)
  useEffect(() => {
    if (nodePanelTick > 0) setSidePanel('node')
  }, [nodePanelTick])

  /* ------------------------------------------------------------------ */
  /* 键盘快捷键                                                          */
  /* ------------------------------------------------------------------ */

  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent): void => {
      // 已经被内层处理掉的按键不再重复处理（例如富文本编辑器自己的快捷键）
      if (e.defaultPrevented) return
      // 输入法组词过程中的按键交给输入法处理
      if (e.isComposing || e.keyCode === 229) return

      const target = e.target as HTMLElement | null
      if (
        target &&
        (target.tagName === 'INPUT' ||
          target.tagName === 'TEXTAREA' ||
          target.tagName === 'SELECT' ||
          target.isContentEditable)
      ) {
        return
      }

      const store = useEditor.getState()
      const selectedId = store.selection[0]

      /**
       * 仍在编辑态时（焦点可能因为点了底部格式栏而离开编辑器），**单键动作一律不接管**：
       * 否则"想输入空格"会被当成折叠主题、想输入字符会被当成删除/新建节点。
       * Ctrl 组合键（保存、撤销、搜索…）照旧放行。
       */
      if (store.editingId && !(e.ctrlKey || e.metaKey)) return

      // Alt+↑ / ↓：同级上移 / 下移（知犀的写法，和 Ctrl+Shift+方向键等价）
      if (e.altKey && (e.key === 'ArrowUp' || e.key === 'ArrowDown')) {
        e.preventDefault()
        store.moveSelectionByKey(e.key)
        return
      }

      // Alt+C：给选中主题打开代码块编辑（面板聚焦到代码输入框）
      if (e.altKey && (e.key === 'c' || e.key === 'C')) {
        e.preventDefault()
        if (selectedId) {
          setSidePanel('node')
          useEditor.getState().requestCodeFocus()
        }
        return
      }

      if (e.ctrlKey || e.metaKey) {
        const key = e.key.toLowerCase()
        if (key === 'z') {
          e.preventDefault()
          if (e.shiftKey) store.redo()
          else store.undo()
        } else if (key === 'y') {
          e.preventDefault()
          store.redo()
        } else if (key === 'c') {
          e.preventDefault()
          store.copySelection()
        } else if (key === 'v') {
          e.preventDefault()
          // 依次试：剪贴板图片 → 带 Markdown 标记的文本 → 内部复制的节点
          void (async () => {
            if (!store.editingId && selectedId) {
              const image = await readClipboardImage()
              if (image) {
                useEditor
                  .getState()
                  .setImage(selectedId, { path: image.path, width: image.width, height: image.height })
                showToast(
                  image.width > 0
                    ? `已把剪贴板图片贴到选中的主题（${image.width}×${image.height}）`
                    : '已把剪贴板图片贴到选中的主题（未取到像素尺寸，按默认大小显示）'
                )
                return
              }

              // 文本里带 Markdown 标记（`==高亮==`、`^上标^`、`A[^1]`…）→ 建成带格式的子主题。
              // 编辑器内粘贴由 RichTextEditor 自己处理；这里是"选中节点、没在编辑"时的路径。
              const text = await window.api.readClipboardText().catch(() => '')
              const lines = text
                .split(/\r?\n/)
                .map((line) => line.trim())
                .filter((line) => line.length > 0 && looksLikeMarkdown(line))
              if (lines.length > 0) {
                const items = lines.map((line) => {
                  const inline = parseInlineMarkdown(line)
                  return { title: inline.text, rich: inlineRunsToRich(inline.runs) }
                })
                const count = useEditor.getState().addRichChildren(selectedId, items)
                showToast(`已按 Markdown 粘贴 ${count} 个带格式的子主题（可用 Ctrl+Z 撤回）`)
                return
              }
            }
            useEditor.getState().paste()
          })()
        } else if (key === 'f') {
          // Ctrl+F：打开搜索面板（与 Xmind 一致）
          e.preventDefault()
          setSidePanel('search')
        } else if (e.key === '/') {
          // Ctrl+/：折叠 / 展开。空格已经让给"直接输入空格"（选中后直接打字即进入编辑）
          e.preventDefault()
          if (selectedId) store.toggleCollapse(selectedId)
        } else if (
          // 编辑态里 Ctrl+Shift+方向键交给浏览器/编辑器（选词），不要去挪节点
          !store.editingId &&
          e.shiftKey &&
          (e.key === 'ArrowUp' ||
            e.key === 'ArrowDown' ||
            e.key === 'ArrowLeft' ||
            e.key === 'ArrowRight' ||
            e.key === 'Home' ||
            e.key === 'End')
        ) {
          // Ctrl+Shift+方向键：选中主题的精确移动（与亿图脑图一致）
          e.preventDefault()
          store.moveSelectionByKey(e.key)
        }
        return
      }

      switch (e.key) {
        case 'Tab':
          e.preventDefault()
          store.addChild(selectedId)
          break
        case 'Enter':
          e.preventDefault()
          store.addSibling(selectedId)
          break
        case 'F2':
          if (selectedId) {
            e.preventDefault()
            store.beginEdit(selectedId)
          }
          break
        case 'Delete':
        case 'Backspace':
          e.preventDefault()
          store.deleteSelection()
          break
        case 'ArrowUp':
        case 'ArrowDown':
        case 'ArrowLeft':
        case 'ArrowRight':
          e.preventDefault()
          store.navigateSelection(e.key)
          break
        default:
          /**
           * 选中主题后**直接打字就进入编辑**（Xmind 的手感）。
           *
           * 两条防呆：
           * 1. 空格只用来"进入编辑"，**不落字**——输入法用空格选词、用户也可能只是
           *    习惯性按一下，在空白框里留下一个前导空格没有任何意义；
           * 2. 其它字符落字后**寄存**一笔（`stageTypedChar`）：它可能只是拼音的第一个
           *    字母（输入法组词时的第一个 keydown 完全看不出组词迹象），
           *    编辑器发现真正的组词开始后会把这个字符让给输入法，避免空框里冒出 `w` 这种怪字符。
           */
          if (selectedId && !e.altKey && e.key.length === 1) {
            e.preventDefault()
            if (e.key === ' ') {
              store.beginEdit(selectedId)
            } else {
              store.beginEdit(selectedId, e.key)
              stageTypedChar(selectedId, e.key)
            }
          }
          break
      }
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [])

  /* ------------------------------------------------------------------ */
  /* 拖拽图片文件到窗口：贴到选中的主题                                     */
  /* ------------------------------------------------------------------ */

  useEffect(() => {
    // 文档文件（.xmind 等）不拦：不 preventDefault，让 Chromium 的默认导航发生，
    // 主进程的 will-navigate 拦截器才能接住并走「打开文档」流程
    const DOCUMENT_RE = /\.(xmind|emmx|emm)$/i
    const pickImageFile = (files: FileList | null): File | null => {
      if (!files) return null
      for (const file of Array.from(files)) {
        if (DOCUMENT_RE.test(file.name)) return null // 混着文档时整体交给文档流程
        if (file.type.startsWith('image/') || /\.(png|jpe?g|gif|bmp|webp|svg|avif)$/i.test(file.name)) {
          return file
        }
      }
      return null
    }
    const onDragOver = (event: DragEvent): void => {
      if (pickImageFile(event.dataTransfer?.files ?? null)) event.preventDefault()
    }
    const onDrop = (event: DragEvent): void => {
      const file = pickImageFile(event.dataTransfer?.files ?? null)
      if (!file) return
      event.preventDefault()
      void (async () => {
        try {
          const bytes = new Uint8Array(await file.arrayBuffer())
          const image = await window.api.addImage(activeDocId(), file.name, bytes)
          const store = useEditor.getState()
          const id = store.selection[0]
          if (!image || !id) {
            showToast('请先选中一个主题，再把图片拖进来')
            return
          }
          store.setImage(id, { path: image.path, width: image.width, height: image.height })
          showToast(
            image.width > 0
              ? `已插入图片 ${file.name}（${image.width}×${image.height}）`
              : `已插入图片 ${file.name}（未取到像素尺寸，按默认大小显示）`
          )
        } catch (error) {
          showToast(`插入图片失败：${(error as Error).message}`)
        }
      })()
    }
    window.addEventListener('dragover', onDragOver)
    window.addEventListener('drop', onDrop)
    return () => {
      window.removeEventListener('dragover', onDragOver)
      window.removeEventListener('drop', onDrop)
    }
  }, [showToast])

  /* ------------------------------------------------------------------ */

  const displayName = fileNameOf(filePath) ?? '未命名导图'

  return (
    <div className="app">
      <Toolbar
        outlineOpen={showOutline}
        hiddenItems={toolbarHidden}
        onToggleHidden={(id, hidden) => {
          const current = useEditor.getState().appSettings.toolbarHidden
          const next = hidden
            ? current.includes(id)
              ? current
              : [...current, id]
            : current.filter((item) => item !== id)
          void patchAppSettings({ toolbarHidden: next })
        }}
        actions={{
          onNew: () => newDocument(),
          onOpen: () => void openDocument(),
          onSave: () => void saveDocument(false),
          onSaveAs: () => void saveDocument(true),
          onHelp: () => setShowShortcuts(true),
          onThemes: () => setSidePanel((current) => (current === 'theme' ? 'none' : 'theme')),
          onNodes: () => setSidePanel((current) => (current === 'node' ? 'none' : 'node')),
          onOutline: () => setShowOutline((current) => !current),
          onSearch: () => setSidePanel((current) => (current === 'search' ? 'none' : 'search')),
          // 与「更多」里的同名入口走同一个实现，避免两套语义
          onRelayout: () => useEditor.getState().clearAllPositions(),
          onFormula: () => {
            setSidePanel('node')
            useEditor.getState().requestFormulaFocus()
          },
          onCode: () => {
            setSidePanel('node')
            useEditor.getState().requestCodeFocus()
          },
          onExport: () => setShowExport(true),
          onImportTheme: () => void importTheme(),
          onImportMarkdown: () => void importOutlineFile('markdown'),
          onImportOpml: () => void importOutlineFile('opml'),
          onExportOutline: (format) => void exportOutlineAs(format),
          onAiGenerate: () => setAiTask('generate'),
          onAiExpand: () => setAiTask('expand'),
          onAiPolish: () => setAiTask('polish'),
          onAiSettings: () => setShowAiSettings(true),
          onHistory: () => setShowHistory(true),
          onNewWindow: openNewWindow,
          onOpenSheetWindow: openCopyWindow
        }}
      />

      <div className={showOutline ? 'app__body app__body--with-outline' : 'app__body'}>
        {showOutline && <OutlinePanel onClose={() => setShowOutline(false)} onNotify={showToast} />}
        <Canvas />
        {sidePanel === 'theme' && (
          <ThemePanel
            onClose={() => setSidePanel('none')}
            onNotify={showToast}
            onSetDefaultTheme={handleSetDefaultTheme}
          />
        )}
        {sidePanel === 'node' && <NodePanel onClose={() => setSidePanel('none')} onNotify={showToast} />}
        {sidePanel === 'search' && <SearchPanel onClose={() => setSidePanel('none')} onNotify={showToast} />}
      </div>

      {/* 仅在进入编辑态时出现；「默认样式」面板改渲染兜底值后要让测量缓存失效 */}
      <RichFormatBar onRenderDefaultsChanged={onDefaultStyleChanged} />

      {/* 底部多文档标签栏（浏览器式任务栏）：点标签切换文档 */}
      <TabBar onNewTab={() => newDocument()} onCloseTab={closeTabById} />

      <StatusBar />

      {recovery && (
        <RecoveryDialog
          info={recovery}
          onRestore={() => void handleRestore()}
          onDiscard={handleDiscardRecovery}
        />
      )}

      {pending && (
        <UnsavedDialog
          fileName={pending.fileName || displayName}
          onCancel={() => setPending(null)}
          onDiscard={() => {
            const action = pending
            setPending(null)
            // 关标签/退出的「不保存」：先做自己的收尾（标记强制关闭等），再继续流程
            if (action.discard) action.discard()
            else action.run()
          }}
          onSave={() => {
            const action = pending
            setPending(null)
            void saveDocument(false).then((ok) => {
              if (ok) action.run()
            })
          }}
        />
      )}

      {showShortcuts && <ShortcutsDialog onClose={() => setShowShortcuts(false)} />}

      {showExport && <ExportDialog onClose={() => setShowExport(false)} onNotify={showToast} />}

      {aiTask && (
        <AiDialog
          task={aiTask}
          onClose={() => setAiTask(null)}
          onNotify={showToast}
          onGenerateInNewWindow={openGeneratedInNewWindow}
        />
      )}

      {showAiSettings && (
        <AiSettingsDialog onClose={() => setShowAiSettings(false)} onNotify={showToast} />
      )}

      {showHistory && (
        <HistoryDialog
          onClose={() => setShowHistory(false)}
          onNotify={showToast}
          onOpenFile={(path) => void openPath(path)}
          onRestore={(snapshotId) => guard(() => void restoreSnapshot(snapshotId))}
        />
      )}

      {toast && <div className="toast">{toast}</div>}
    </div>
  )
}

import { useCallback, useEffect, useMemo, useRef, useState, type PointerEvent as ReactPointerEvent, type ReactElement } from 'react'
import { layoutSheet, LAYOUT_DEFAULTS } from '@shared/layout'
import type { LayoutResult } from '@shared/layout/types'
import { OVERLAY_TITLE_LINE_HEIGHT, overlayTitleLines } from '@shared/layout/overlays'
import { readOverlayTextStyle } from '@shared/model/overlay-style'
import type { Topic } from '@shared/model/types'
import { activeRoot, activeSheet, findParent, findTopic, isSelfOrDescendant } from '@shared/model/tree'
import { alsoDraggedOf, moveRootsOf, resolveDragMove, type DragMove } from '@shared/model/dragmove'
import {
  blockReasonOf,
  distanceToRect,
  nearestInRegion,
  nearestSiblingGap,
  perpendicularOf,
  resolveDrop,
  stackDirection,
  zoneOf,
  type DropAxis,
  type DropMode,
  type DropPoint,
  type DropRect,
  type DropResult,
  type SiblingStack,
  type SnapNode
} from '@shared/model/drop'
import { applyTopicFilter, hitTopicIds, isFilterActive, searchSheet } from '@shared/search'
import { DEFAULT_STRUCTURE, getStructureDef } from '@shared/xmind/constants'
import { measureTopic, bumpMeasureEpoch } from '../render/measure'
import { useDebouncedValue } from '../hooks/useDebouncedValue'
import { clearFormulaCache } from '../render/formula'
import { branchColorOf } from '../render/theme'
import { viewportActions } from '../render/viewport'
import { themeColorsOf, useEditor } from '../store/editor'
import TopicNode from './TopicNode'

/**
 * 可吸附区域在**生长方向**上的外扩量——那里是新子主题会待的一整片区域，所以放得宽。
 *
 * 判定不能只用"到节点的直线距离"：那是**各向同性**的，而落点窗口天生是各向异性的——
 * 生长方向上能落进一整列，同级方向上只有"相邻兄弟之间那条缝"。
 * 一个半径去卡两件事，必然一边太松一边太紧，怎么调都不对
 * （这条结论来自成熟实现 simple-mind-map 的 Drag 插件：它也是分轴判定的）。
 */
const GROWTH_REACH = Math.round(LAYOUT_DEFAULTS.gapX * 1.5)

/**
 * 沿**同级方向**（以及背向生长的那一侧）的外扩量：只留一点点容错，够盖住那条缝即可。
 * 缝隙更大时由 `nearestSiblingGap` 那条规则兜底（它专门管"插进两个同级之间"）。
 */
const SIBLING_REACH = Math.round(LAYOUT_DEFAULTS.gapY * 1.6)

/**
 * 某一层**最外侧**（那一边没有相邻兄弟）向外多留的吸附带。
 *
 * 用途：把一个主题放到"最后一个子主题之后稍远一点的空白"时，仍然算
 * 「插到它后面」＝给父主题追加一个子主题——这正是大家最常用的追加动作。
 * 放在更远的地方才落到自由摆放。
 */
const OUTER_REACH = Math.round(LAYOUT_DEFAULTS.gapY * 2.4)

/** 粗筛半径：任何方向的外扩都不会超过它，比它远的节点不必细算区域 */
const SNAP_PREFILTER = Math.max(GROWTH_REACH, OUTER_REACH) + OUTER_REACH + 8

/**
 * 落点迟滞：指针要换到**另一个**落点前，必须先移动这么远。
 *
 * 单位是**世界单位**（会乘上当次缩放再和屏幕位移比较）：
 * 画布缩到 50% 时，"走够这么远"对应的屏幕位移自然翻倍，手感才和 100% 时一致。
 *
 * 没有它，指针停在"成为子主题"与"插到同级之间"的分界线上时，
 * 落点会一帧一个样地来回跳，看起来就是"吸附乱跳、提示乱闪"。
 * 有了它，同一个落点只要还够得着就保持不动，手感立刻稳定下来。
 */
const DROP_HYSTERESIS = 14

/**
 * 空位框里显示的标题：按可用宽度粗略截断，避免文字溢出虚线框。
 * 中日韩字符按整宽算，其余按半宽算。
 */
function clipText(text: string, width: number, fontSize = 12): string {
  const plain = text.replace(/\s+/g, ' ').trim()
  const limit = Math.max(0, width - 12)
  let used = 0
  let out = ''
  for (const ch of plain) {
    const charWidth = /[\u2e80-\u9fff\uff00-\uffef]/.test(ch) ? fontSize : fontSize * 0.55
    if (used + charWidth > limit) return `${out}…`
    used += charWidth
    out += ch
  }
  return out
}

interface AxisPair {
  stack: DropAxis | null
  growth: DropAxis | null
}

export default function Canvas(): ReactElement {
  const containerRef = useRef<HTMLDivElement | null>(null)
  const [size, setSize] = useState({ width: 0, height: 0 })

  const workbook = useEditor((s) => s.workbook)
  const docSeq = useEditor((s) => s.docSeq)
  const zoom = useEditor((s) => s.zoom)
  const pan = useEditor((s) => s.pan)
  const viewLock = useEditor((s) => s.viewLock)
  const selection = useEditor((s) => s.selection)
  const selectedOverlay = useEditor((s) => s.selectedOverlay)
  const editingId = useEditor((s) => s.editingId)
  const editingText = useEditor((s) => s.editingText)
  const editingRich = useEditor((s) => s.editingRich)
  const setPan = useEditor((s) => s.setPan)
  const setZoom = useEditor((s) => s.setZoom)
  const search = useEditor((s) => s.search)
  const filter = useEditor((s) => s.filter)

  const [dragVisual, setDragVisual] = useState<{
    /** 手里抓着的那一个（多选时是抓的那个，不是整群的第一个） */
    anchorId: string
    dx: number
    dy: number
    moving: DragMove
    /** 整群被拖时，用来把「点谁拖谁」说明白 */
    group: number
  } | null>(null)
  /**
   * 拖拽节点时的落点预测：
   * child = 松手后成为目标的**子主题**（高亮目标节点）；
   * after = 松手后**排到目标后面**（同级排序，在目标外侧显示插入条）。
   * 目标是自己的父级时什么都不会发生，此时为 null，不给任何提示。
   */
  const [dropTarget, setDropTarget] = useState<{ id: string; mode: DropMode } | null>(null)
  /**
   * 一级主题被拖到中心主题**另一侧**的空白处时，将要切到的那一侧。
   * 这是知犀 / Xmind 的「左右位置调整」：不需要"可放置"标记，松手即对调。
   */
  const [sideTarget, setSideTarget] = useState<'left' | 'right' | null>(null)

  /** 拖动落点框里显示的「是谁要落到这里」 */
  const [dropLabel, setDropLabel] = useState('')
  /** 指针落在真正的空白处：松手会自由摆放（而不是吸附进树里） */
  const [freeDrop, setFreeDrop] = useState(false)
  /**
   * 落点被判为非法的原因（例如「它已经是这个主题的子主题了」）。
   *
   * 拖拽里"挨着了却什么都不发生"最容易被误当成卡死——把原因写出来，
   * 用户才知道这是有意为之而不是软件坏了。
   */
  const [dropBlocked, setDropBlocked] = useState('')

  /** 左键框选：矩形用容器内的局部坐标，便于直接定位 */
  const [marquee, setMarquee] = useState<{ x0: number; y0: number; x1: number; y1: number } | null>(null)

  /** 双击画布上的边界/概要/关系线标题后，就地编辑文字 */
  const [titleEdit, setTitleEdit] = useState<{
    kind: 'boundary' | 'summary' | 'relationship'
    id: string
    x: number
    y: number
    anchor: 'start' | 'middle' | 'end'
    value: string
  } | null>(null)
  /** Esc 取消时置位，避免失焦又把取消的内容写回去 */
  const cancelTitleRef = useRef(false)

  /** 正在拖拽的关系线端点（拖到别的主题上即可改接） */
  const [handleDrag, setHandleDrag] = useState<{
    relationshipId: string
    end: 'end1Id' | 'end2Id'
    /** 不动的那一端（世界坐标），用来画预览线 */
    anchor: { x: number; y: number }
    pointer: { x: number; y: number }
    targetId: string | null
  } | null>(null)

  /* ---- 供原生事件处理器读取的最新值 ---- */
  const zoomRef = useRef(zoom)
  zoomRef.current = zoom
  const panRef = useRef(pan)
  panRef.current = pan
  const rootRef = useRef<Topic>(activeRoot(workbook))
  rootRef.current = activeRoot(workbook)

  /**
   * 拖拽过程中的「实时值」都放在 ref 里：原生 pointermove 是每帧都可能触发的高频回调，
   * 走 state 会慢半拍，落点会明显跟不上指针。
   */
  const selectionRef = useRef(selection)
  selectionRef.current = selection
  /** 拖动期间固定不变：这次到底在拖哪些主题 */
  const dragNodesRef = useRef<DragMove | null>(null)
  /** 当前裁决出的落点（松手就按它落） */
  const dropPlanRef = useRef<DropResult | null>(null)
  /**
   * 落点迟滞用的「上一次裁决」。
   * 指针换目标前要先走够 `DROP_HYSTERESIS` 像素，避免在分界线上抖动。
   */
  const dropLatchRef = useRef<{
    key: string
    plan: DropResult | null
    side: 'left' | 'right' | null
    free: boolean
    px: number
    py: number
  } | null>(null)
  /** 指针位置与拖拽起点，自动滚动要用 */
  const pointerRef = useRef<{ x: number; y: number; startX: number; startY: number } | null>(null)

  /* ---- 拖拽过程中：贴住画布边缘时自动滚动 ---- */
  const dragAutoScroll = useCallback((): void => {
    const el = containerRef.current
    const pointer = pointerRef.current
    if (!el || !pointer) return
    const rect = el.getBoundingClientRect()
    const EDGE = 72
    const MAX_SPEED = 26
    const speed = (distance: number): number => Math.min(MAX_SPEED, ((EDGE - distance) / EDGE) * MAX_SPEED)

    const left = pointer.x - rect.left
    const right = rect.right - pointer.x
    const top = pointer.y - rect.top
    const bottom = rect.bottom - pointer.y
    let dx = 0
    let dy = 0
    if (left < EDGE) dx = speed(left)
    else if (right < EDGE) dx = -speed(right)
    if (top < EDGE) dy = speed(top)
    else if (bottom < EDGE) dy = -speed(bottom)
    if (dx === 0 && dy === 0) return

    const current = panRef.current
    setPan({ x: current.x + dx, y: current.y + dy })
  }, [setPan])

  /* ---- 拖拽过程中：按 Esc 放弃这次拖拽 ---- */

  /* ---- 布局计算 ---- */
  /**
   * 字体（含 KaTeX 的数学字体）加载完成后，公式的真实宽度才稳定。
   * 这里用它触发一次重新测量与布局，避免首次打开时公式框尺寸偏小。
   */
  const [fontEpoch, setFontEpoch] = useState(0)

  useEffect(() => {
    let cancelled = false
    const fonts = typeof document !== 'undefined' ? document.fonts : undefined
    if (!fonts) return
    void fonts.ready.then(() => {
      if (cancelled) return
      // 两处缓存都要失效：公式尺寸缓存 + 节点测量缓存（后者里存着 formulaBox）
      clearFormulaCache()
      bumpMeasureEpoch()
      setFontEpoch((n) => n + 1)
    })
    return () => {
      cancelled = true
    }
  }, [])

  const renderEpoch = useEditor((s) => s.renderEpoch)

  const layout: LayoutResult = useMemo(() => {
    const root = activeRoot(workbook)
    const sheet = activeSheet(workbook)
    // 正在编辑的节点用「未提交的内容」参与测量，做到边打字边自适应尺寸
    const measure = (topic: Topic, depth: number): ReturnType<typeof measureTopic> =>
      topic.id === editingId && editingRich
        ? measureTopic({ ...topic, title: editingText, titleRich: editingRich }, depth)
        : measureTopic(topic, depth)
    // 关系线/边界/概要在结构布局之后按最终坐标计算，所以要把画布数据一起传进去
    return layoutSheet(root, measure, {}, sheet)
    // fontEpoch / renderEpoch 只用于「强制重新布局」，不是布局的输入
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [workbook, editingId, editingText, editingRich, fontEpoch, renderEpoch])

  const layoutRef = useRef<LayoutResult>(layout)
  layoutRef.current = layout

  /**
   * 吸附用的候选节点表：每帧都要扫一遍，所以按布局算一次就够。
   * 带上 `depth`：距离相同时优先落进更深的节点（和成熟实现一致，见 `nearestInRegion`）。
   */
  const dropCandidates = useMemo(
    () => layout.nodes.map((node) => ({ id: node.id, rect: node, depth: node.depth })),
    [layout]
  )

  /** 当前画布生效的主题配色 */
  const colors = useMemo(() => themeColorsOf(workbook), [workbook])

  /**
   * 边界按颜色分组：同色的多个边界拼成一条 path 一次性填充。
   * 这样即使两个边界区域重叠，也不会因为半透明填充叠加而显得颜色更深。
   */
  const boundaryGroups = useMemo(() => {
    const groups = new Map<string, { d: string; titles: typeof layout.boundaries }>()
    for (const boundary of layout.boundaries) {
      const color = boundary.branchId ? branchColorOf(colors, layout, boundary.branchId) : colors.deepText
      const entry = groups.get(color) ?? { d: '', titles: [] }
      entry.d = entry.d.length > 0 ? `${entry.d} ${boundary.d}` : boundary.d
      entry.titles.push(boundary)
      groups.set(color, entry)
    }
    return Array.from(groups.entries()).map(([color, entry]) => ({ color, ...entry }))
  }, [layout, colors])

  /* ---- 容器尺寸 ---- */
  useEffect(() => {
    const el = containerRef.current
    if (!el) return
    const update = (): void => setSize({ width: el.clientWidth, height: el.clientHeight })
    update()
    const observer = new ResizeObserver(update)
    observer.observe(el)
    return () => observer.disconnect()
  }, [])

  /* ---- 视口动作 ---- */
  const centerRoot = useCallback((): void => {
    const el = containerRef.current
    const lay = layoutRef.current
    if (!el || !lay) return
    const rootNode = lay.nodeMap.get(rootRef.current.id)
    if (!rootNode) return
    const width = el.clientWidth
    const height = el.clientHeight
    if (width === 0 || height === 0) return
    setZoom(1)
    setPan({
      x: width / 2 - (rootNode.x + rootNode.width / 2),
      y: height / 2 - (rootNode.y + rootNode.height / 2)
    })
  }, [setPan, setZoom])

  const fit = useCallback((): void => {
    const el = containerRef.current
    const lay = layoutRef.current
    if (!el || !lay) return
    const width = el.clientWidth
    const height = el.clientHeight
    if (width === 0 || height === 0) return
    const margin = 48
    const scale = Math.min(
      (width - margin * 2) / lay.bounds.width,
      (height - margin * 2) / lay.bounds.height,
      1.5
    )
    const z = Math.max(0.1, Math.min(4, scale))
    setZoom(z)
    setPan({ x: (width - lay.bounds.width * z) / 2, y: (height - lay.bounds.height * z) / 2 })
  }, [setPan, setZoom])

  const zoomTo = useCallback(
    (next: number): void => {
      const el = containerRef.current
      if (!el) return
      const px = el.clientWidth / 2
      const py = el.clientHeight / 2
      const oldZoom = zoomRef.current
      const currentPan = panRef.current
      const z = Math.max(0.1, Math.min(4, next))
      const wx = (px - currentPan.x) / oldZoom
      const wy = (py - currentPan.y) / oldZoom
      setZoom(z)
      setPan({ x: px - wx * z, y: py - wy * z })
    },
    [setPan, setZoom]
  )

  /** 把节点滚动到可见范围内，避免新建的主题落在视口外 */
  const ensureVisible = useCallback(
    (id: string): void => {
      const el = containerRef.current
      const lay = layoutRef.current
      if (!el || !lay) return
      const node = lay.nodeMap.get(id)
      if (!node) return
      const z = zoomRef.current
      const currentPan = panRef.current
      const width = el.clientWidth
      const height = el.clientHeight
      if (width === 0 || height === 0) return
      const margin = 56
      const left = node.x * z + currentPan.x
      const top = node.y * z + currentPan.y
      const right = (node.x + node.width) * z + currentPan.x
      const bottom = (node.y + node.height) * z + currentPan.y

      let dx = 0
      let dy = 0
      if (left < margin) dx = margin - left
      else if (right > width - margin) dx = width - margin - right
      if (top < margin) dy = margin - top
      else if (bottom > height - margin) dy = height - margin - bottom

      if (dx !== 0 || dy !== 0) {
        setPan({ x: currentPan.x + dx, y: currentPan.y + dy })
      }
    },
    [setPan]
  )

  /** 把某个节点移到视口正中（搜索跳转用，缩放保持不变） */
  const centerOn = useCallback(
    (id: string): void => {
      const el = containerRef.current
      const lay = layoutRef.current
      if (!el || !lay) return
      const node = lay.nodeMap.get(id)
      if (!node) return
      const z = zoomRef.current
      const width = el.clientWidth
      const height = el.clientHeight
      if (width === 0 || height === 0) return
      // 让节点中心落在视口中心；搜索面板占了右侧，这里往左让出一点，避免被面板挡住
      const targetX = width / 2 - 150
      const targetY = height / 2
      const centerX = (node.x + node.width / 2) * z
      const centerY = (node.y + node.height / 2) * z
      setPan({ x: targetX - centerX, y: targetY - centerY })
    },
    [setPan]
  )

  useEffect(() => {
    viewportActions.fit = fit
    viewportActions.centerRoot = centerRoot
    viewportActions.zoomTo = zoomTo
    viewportActions.ensureVisible = ensureVisible
    viewportActions.centerOn = centerOn
  }, [fit, centerRoot, zoomTo, ensureVisible, centerOn])

  /* ---- 进入编辑态时保证节点可见（新建主题可能超出视口） ---- */
  useEffect(() => {
    // 视角锁定开着时交给下面的跟随循环处理：它会把编辑中的节点居中，
    // ensureVisible 只保证可见不居中，两套逻辑同时跑会互相打架
    if (!editingId || viewLock) return
    const target = editingId
    const frame = window.requestAnimationFrame(() => viewportActions.ensureVisible(target))
    return () => window.cancelAnimationFrame(frame)
  }, [editingId, viewLock])

  /**
   * 视角锁定要盯住的那个主题。
   *
   * - 选择为空（点了画布空白处）→ 什么都不跟，镜头留给用户自己摆；
   * - 选择指向一个**已经不存在的主题**（刚删完、撤销回到另一个版本）→ 退回中心主题，
   *   而不是"盯不到就彻底不动"——那正是用户看到的「删除后视角不跟随」；
   * - 其余情况就是当前选中的主题。
   */
  const focusId = useMemo(() => {
    if (selection.length === 0) return ''
    const rootTopic = activeRoot(workbook)
    const picked = selection[0]
    return picked && findTopic(rootTopic, picked) ? picked : rootTopic.id
  }, [selection, workbook])

  /**
   * 被盯住的主题在布局里的**位置与尺寸**（拼成字符串，方便直接当依赖）。
   *
   * 用它而不是"布局对象变了"来驱动镜头：删掉一整条主题、改文字让节点变大变小、
   * 拖拽重排、撤销重做……只要**被选中的主题自己动了**，镜头就跟上；
   * 跟它无关的布局变化（别的分支在动）则不会带着镜头乱跑。
   */
  const focusKey = useMemo(() => {
    if (!focusId) return ''
    const node = layout.nodeMap.get(focusId)
    if (!node) return `${focusId}|?`
    return (
      `${focusId}|${Math.round(node.x)},${Math.round(node.y)},` +
      `${Math.round(node.width)},${Math.round(node.height)}`
    )
  }, [focusId, layout])

  /* ---- 视角锁定：把选中的主题稳稳按在视口中央 ---- */
  useEffect(() => {
    // 正在拖主题时不跟：镜头要是同时在移，指针下的画面会跟着滑，落点就抓不准了。
    // 松手（dragVisual 归零）后视野再咬住它。
    if (!viewLock || dragVisual || !focusId || !focusKey) return
    const id = focusId
    const el = containerRef.current
    if (!el) return
    if (el.clientWidth === 0 || el.clientHeight === 0) return

    let raf = 0
    /** 目标一时还没出现在布局里（刚删完、刚打开）就先等几帧，别急着放弃 */
    let misses = 0
    const MAX_MISSES = 90

    /**
     * 逐帧向"该有的平移量"收敛，而不是一步跳过去：
     * 一步到位时整张图会「啪」地闪一下，眼睛跟不住到底是哪个主题被选中了；
     * 缓动过去才像镜头跟着走。收敛到亚像素就停手，不再空转。
     *
     * 依赖里带上 `zoom`：按住 Ctrl 滚轮缩放时视角会钉在选中的主题上（以它为中心缩放），
     * 而不是把主题缩放跑出屏幕。手动拖动画布则不会触发这里——想让镜头暂停跟随时
     * 直接拖就是了，下一次选择或位置变化它才重新咬住。
     */
    const step = (): void => {
      const node = layoutRef.current?.nodeMap.get(id)
      const width = el.clientWidth
      const height = el.clientHeight
      if (width === 0 || height === 0) return
      if (!node) {
        if (misses < MAX_MISSES) {
          misses += 1
          raf = window.requestAnimationFrame(step)
        }
        return
      }
      const z = zoomRef.current
      const wantX = width / 2 - (node.x + node.width / 2) * z
      const wantY = height / 2 - (node.y + node.height / 2) * z
      const current = panRef.current
      const dx = wantX - current.x
      const dy = wantY - current.y
      if (Math.abs(dx) < 0.5 && Math.abs(dy) < 0.5) {
        setPan({ x: wantX, y: wantY })
        return
      }
      setPan({ x: current.x + dx * 0.22, y: current.y + dy * 0.22 })
      raf = window.requestAnimationFrame(step)
    }

    raf = window.requestAnimationFrame(step)
    return () => window.cancelAnimationFrame(raf)
    // focusKey 里已经含了被盯主题的 id 与几何，用它做依赖即可（不写进函数体会被 lint 挑刺）
  }, [viewLock, dragVisual, focusId, focusKey, editingId, zoom, size.width, size.height, setPan])

  /* ---- 新文档打开后居中 ---- */
  const centeredSeqRef = useRef(-1)
  useEffect(() => {
    if (size.width === 0 || size.height === 0) return
    if (centeredSeqRef.current === docSeq) return
    centeredSeqRef.current = docSeq
    centerRoot()
  }, [size.width, size.height, docSeq, centerRoot])

  /* ---- 滚轮：平移 / Ctrl 缩放 ---- */
  useEffect(() => {
    const el = containerRef.current
    if (!el) return
    const onWheel = (ev: WheelEvent): void => {
      ev.preventDefault()
      const currentPan = panRef.current
      if (ev.ctrlKey || ev.metaKey) {
        const rect = el.getBoundingClientRect()
        const px = ev.clientX - rect.left
        const py = ev.clientY - rect.top
        const oldZoom = zoomRef.current
        const z = Math.max(0.1, Math.min(4, oldZoom * Math.exp(-ev.deltaY * 0.0015)))
        const wx = (px - currentPan.x) / oldZoom
        const wy = (py - currentPan.y) / oldZoom
        setZoom(z)
        setPan({ x: px - wx * z, y: py - wy * z })
      } else {
        setPan({ x: currentPan.x - ev.deltaX, y: currentPan.y - ev.deltaY })
      }
    }
    el.addEventListener('wheel', onWheel, { passive: false })
    return () => el.removeEventListener('wheel', onWheel)
  }, [setPan, setZoom])

  /* ---- 命中测试与坐标换算 ---- */
  const screenToWorld = useCallback((clientX: number, clientY: number): { x: number; y: number } => {
    const el = containerRef.current
    if (!el) return { x: 0, y: 0 }
    const rect = el.getBoundingClientRect()
    const z = zoomRef.current
    const p = panRef.current
    return { x: (clientX - rect.left - p.x) / z, y: (clientY - rect.top - p.y) / z }
  }, [])

  const hitTest = useCallback((wx: number, wy: number, excludeId = ''): string | null => {
    const lay = layoutRef.current
    if (!lay) return null
    const root = rootRef.current
    for (let i = lay.nodes.length - 1; i >= 0; i -= 1) {
      const node = lay.nodes[i]
      if (node.x <= wx && wx <= node.x + node.width && node.y <= wy && wy <= node.y + node.height) {
        // excludeId 为空串时不会命中任何子树，等价于「不排除任何节点」
        if (isSelfOrDescendant(root, excludeId, node.id)) continue
        return node.id
      }
    }
    return null
  }, [])

  /**
   * 落点判定用的**一次性索引**，随布局重算（一次遍历）。
   *
   * 拖拽时每一帧、每个候选节点都要问「它的子节点往哪排、同级往哪排」，
   * 而这些答案只跟当前布局有关。原先每次都走 `findTopic` / `findParent` 全树遍历，
   * 复杂度是 O(每帧候选数 × 节点数)，节点一多就明显掉帧；
   * 换成查表后运行时全是 O(1)。
   *
   * 算法本身一行没改，只是把「现算」换成「预计算」。
   */
  const dropIndex = useMemo(() => {
    const childrenOf = new Map<string, string[]>()
    const parentOf = new Map<string, string | null>()
    const stackOf = new Map<string, SiblingStack>()
    const stacks: SiblingStack[] = []

    const visit = (topic: Topic, parentId: string | null): void => {
      parentOf.set(topic.id, parentId)
      childrenOf.set(
        topic.id,
        topic.children.map((child) => child.id)
      )
      for (const child of topic.children) visit(child, topic.id)

      // 同级节点堆：同一父级下 ≥2 个**有坐标**的子节点
      if (topic.children.length >= 2) {
        const children: Array<{ id: string; rect: DropRect }> = []
        for (const child of topic.children) {
          const rect = layout.nodeMap.get(child.id)
          if (rect) children.push({ id: child.id, rect })
        }
        if (children.length >= 2) {
          const stack: SiblingStack = { parentId: topic.id, children }
          stacks.push(stack)
          for (const child of children) stackOf.set(child.id, stack)
        }
      }
    }
    visit(activeRoot(workbook), null)

    return { childrenOf, parentOf, stackOf, stacks }
  }, [workbook, layout])

  /** 所有「同级节点堆」：在空白处识别"插到这两个之间"，以及推断同级排列方向 */
  const siblingStacks = dropIndex.stacks

  /** 目标的子节点往哪个方向排（拿不到就返回 null，交给调用方兜底） */
  const childGrowth = useCallback(
    (targetId: string): DropAxis | null => {
      const lay = layoutRef.current
      const targetRect = lay?.nodeMap.get(targetId)
      if (!lay || !targetRect) return null
      const childRects: DropRect[] = []
      for (const childId of dropIndex.childrenOf.get(targetId) ?? []) {
        const rect = lay.nodeMap.get(childId)
        if (rect) childRects.push(rect)
      }
      const last = childRects[childRects.length - 1]
      const secondLast = childRects[childRects.length - 2]
      if (last && secondLast) return stackDirection(secondLast, last)
      if (last) return stackDirection(targetRect, last)
      return null
    },
    [dropIndex]
  )

  /**
   * 目标节点周围的两条方向轴，**全部由实际坐标推出**：
   * - stack：同级节点往哪边排（"插到它后面"看这条）；
   * - growth：它的子节点往哪边长。
   * 平衡思维导图的子节点是竖着排的、组织架构图是横着排的，
   * 靠实际坐标推就不用按结构名写特例，也不会把落点画到错误的一侧。
   */
  const axesOf = useCallback(
    (targetId: string): AxisPair => {
      const lay = layoutRef.current
      const targetRect = lay?.nodeMap.get(targetId)
      if (!lay || !targetRect) return { stack: null, growth: null }

      let stack: DropAxis | null = null
      const owningStack = dropIndex.stackOf.get(targetId)
      if (owningStack) {
        const index = owningStack.children.findIndex((child) => child.id === targetId)
        const next = owningStack.children[index + 1]
        const previous = index > 0 ? owningStack.children[index - 1] : undefined
        // 用相邻兄弟定方向，比用"父 → 子"可靠得多
        const neighbor = next ?? previous
        if (neighbor) {
          const toward = next
            ? stackDirection(targetRect, neighbor.rect)
            : stackDirection(neighbor.rect, targetRect)
          // 同级方向必须**垂直于生长方向**。平衡思维导图的一级主题分列左右，
          // 它们的坐标差只是"左右"，不是真正的同级排列方向，不能拿来当落点依据。
          const growthNow = childGrowth(targetId)
          if (!growthNow || toward.axis !== growthNow.axis) stack = toward
        }
      }

      // 「成为它的子主题」时新节点往哪里长：同一个目标在**两处**都要用这个方向
      // （判断指针是否落在它外侧、以及把空位框摆在哪儿），抽出来才能保证两处一致。
      const growth = childGrowth(targetId) ?? (stack ? perpendicularOf(stack) : null)

      return { stack, growth }
    },
    [dropIndex, childGrowth]
  )

  /**
   * 目标的父级那一层，子节点是往哪个方向排的。
   * 用在「目标自己还没有子节点、推不出生长方向」的时候：
   * 新子主题会排在目标的兄弟之后，所以父级那一层的排列方向的**垂直方向**才是它生长的方向。
   */
  const parentStackAxis = useCallback(
    (targetId: string): DropAxis | null => {
      const parentId = dropIndex.parentOf.get(targetId)
      const parentRect = parentId ? layoutRef.current?.nodeMap.get(parentId) : undefined
      if (!parentRect) return null
      const kids = dropIndex.childrenOf.get(parentId ?? '') ?? []
      const a = kids.length > 1 ? layoutRef.current?.nodeMap.get(kids[0]!) : undefined
      const b = kids.length > 1 ? layoutRef.current?.nodeMap.get(kids[1]!) : undefined
      if (a && b) return stackDirection(a, b)
      // 只有一个子节点时，用"父 → 子"的方向当这一层的排列方向
      const only = layoutRef.current?.nodeMap.get(kids[0] ?? '')
      return only ? stackDirection(parentRect, only) : null
    },
    [dropIndex]
  )

  /**
   * 「成为它的子主题」时新节点会往哪边长。注意这里**不拿子节点去推**：
   * 目标是折叠的、或还没有子节点时推不出方向，那就说明新节点会直接长在目标旁边——
   * 此时用「同级排列方向的垂直方向」，否则新版图里"落在中心主题身上"会把空位框
   * 画到第一个分支的正上方，看着像要排到它前面去。
   */
  const growthAxis = useCallback((pair: AxisPair): DropAxis => {
    if (pair.growth) return pair.growth
    if (pair.stack) return perpendicularOf(pair.stack)
    return { axis: 'x', forward: true }
  }, [])

  /** 目标在它那一层有没有同级兄弟（中心主题在深度 0，天然没有）。 */
  const hasSiblings = useCallback(
    (targetId: string): boolean => dropIndex.stackOf.has(targetId),
    [dropIndex]
  )

  /**
   * 「插到它前 / 后」时，**那一层**的排列方向轴。
   *
   * 必须和 `zoneForPointer` 用同一个答案：否则会出现"提示条画在一侧、松手却插到另一侧"
   * 这种自相矛盾的提示——研究文档里用户截图反映的正是这类问题。
   *
   * - 有同级：就是相邻兄弟的坐标差（比"父 → 子"可靠得多）；
   * - 没有同级（中心主题、独苗子主题）：退回**父级那一层的排列方向**的垂直方向，
   *   那恰好就是"它这个层级往哪边排"。
   */
  const insertAxis = useCallback(
    (targetId: string, pair: AxisPair): DropAxis => {
      if (pair.stack) return pair.stack
      return perpendicularOf(
        pair.growth ?? parentStackAxis(targetId) ?? ({ axis: 'x', forward: true } as DropAxis)
      )
    },
    [parentStackAxis]
  )

  /**
   * 节点的「可吸附区域」＝本体按两条轴**分别**外扩：
   *
   * - 沿**生长方向**（子节点会待的那一侧）放宽到 `GROWTH_REACH`：
   *   在一个向右长的结构里，拖到某个主题右侧那一片空白本来就是"成为它的子主题"；
   * - 沿**同级方向**：朝相邻兄弟那一侧只留 `SIBLING_REACH`（刚好盖住那条缝）；
   *   而**最外侧**（那一边没有兄弟）留 `OUTER_REACH`——这样"放在最后一个子主题之后
   *   稍远一点"仍然算「插到它后面」＝给父主题追加一个子主题；
   * - 背向生长的一侧只用 `SIBLING_REACH`，别把父级那一带白白圈进来。
   *
   * 区域之间可以重叠，最终谁胜出由 `nearestInRegion` 按"离本体最近、更深优先"决定。
   */
  const snapRegionOf = useCallback(
    (targetId: string): DropRect | null => {
      const rect = layoutRef.current?.nodeMap.get(targetId)
      if (!rect) return null
      const pair = axesOf(targetId)
      const growth = growthAxis(pair)
      const stack = pair.stack ?? insertAxis(targetId, pair)
      const horizontal = growth.axis === 'x'
      const forward = growth.forward

      const owning = dropIndex.stackOf.get(targetId)
      let slackPrev = OUTER_REACH
      let slackNext = OUTER_REACH
      if (owning) {
        const index = owning.children.findIndex((c) => c.id === targetId)
        if (index > 0) slackPrev = SIBLING_REACH
        if (index + 1 < owning.children.length) slackNext = SIBLING_REACH
      }
      // 正方向到底是"下一个兄弟"还是"上一个兄弟"，由同级轴的朝向决定
      const negativeSlack = stack?.forward ? slackPrev : slackNext
      const positiveSlack = stack?.forward ? slackNext : slackPrev

      const left = horizontal ? (forward ? SIBLING_REACH : GROWTH_REACH) : negativeSlack
      const right = horizontal ? (forward ? GROWTH_REACH : SIBLING_REACH) : positiveSlack
      const top = horizontal ? negativeSlack : forward ? SIBLING_REACH : GROWTH_REACH
      const bottom = horizontal ? positiveSlack : forward ? GROWTH_REACH : SIBLING_REACH
      return {
        x: rect.x - left,
        y: rect.y - top,
        width: rect.width + left + right,
        height: rect.height + top + bottom
      }
    },
    [axesOf, growthAxis, insertAxis, siblingStacks]
  )

  /**
   * 指针落在目标节点的哪个分区（`child` / `before` / `after`）。
   *
   * - 目标**有同级**：沿同级排列方向分区，贴前/后段插到它前/后、中间成为它的子主题；
   * - 目标**没有同级**（中心主题、独苗子主题）：「插到它前 / 后」用的是**它那一层**的排列
   *   方向（见 `insertAxis`）。中心主题更极端——它没有父级，`resolveDrop` 会把 before/after
   *   一律收敛成"成为它的子主题"，所以它身上再也不会冒出自相矛盾的落点提示。
   */
  const zoneForPointer = useCallback(
    (targetId: string, rect: DropRect, world: DropPoint): DropMode => {
      const pair = axesOf(targetId)
      if (hasSiblings(targetId)) return zoneOf(rect, world, pair.stack)
      return zoneOf(rect, world, insertAxis(targetId, pair))
    },
    [axesOf, hasSiblings, insertAxis]
  )

  /**
   * 一级主题被拖到中心主题**另一侧**的空白处时，返回要切到的那一侧。
   * 只有「向两侧展开」的思维导图才谈得上左右，逻辑图 / 树形图 / 组织架构图都是单侧的。
   *
   * 「另一侧」是按**中心主题的边框**判定的，不是它的中心线：
   * 节点本身有宽度，用中心线会让"贴着中心主题边缘"的那一大片区域被算成同一侧，
   * 于是往左拖一小段毫无反应——那正是「拖了没反应」的常见来源。
   */
  const sideFlipTarget = useCallback(
    (world: DropPoint, draggedId: string): 'left' | 'right' | null => {
      const lay = layoutRef.current
      if (!lay) return null
      const rootTopic = rootRef.current
      const rootRect = lay.nodeMap.get(rootTopic.id)
      const selfRect = lay.nodeMap.get(draggedId)
      const parent = findParent(rootTopic, draggedId)
      if (!rootRect || !selfRect || !parent || parent.id !== rootTopic.id) return null
      // 只有"向两侧展开"的思维导图结构才有左右可言；逻辑图、树形图、组织架构图都是单侧的
      if (getStructureDef(rootTopic.structureClass ?? DEFAULT_STRUCTURE).family !== 'mindmap') return null
      const current: 'left' | 'right' =
        selfRect.x + selfRect.width / 2 < rootRect.x + rootRect.width / 2 ? 'left' : 'right'
      // 指针落在中心主题的左右边框之外才算「换到那一侧」；压在中心主题身上时维持原侧
      const wanted: 'left' | 'right' =
        world.x < rootRect.x ? 'left' : world.x > rootRect.x + rootRect.width ? 'right' : current
      return wanted === current ? null : wanted
    },
    []
  )

  /* ---- 拖动节点 ---- */
  const handleNodePointerDown = useCallback(
    (e: ReactPointerEvent<HTMLDivElement>, id: string): void => {
      if (e.button !== 0) return
      e.stopPropagation()
      const store = useEditor.getState()
      if (store.editingId === id) return
      if (store.editingId) store.commitEdit()

      const rootTopic = rootRef.current
      // 中心主题是整张图的锚点，没有父级可去，也不该被摆到别处
      if (id === rootTopic.id) {
        store.select(id)
        return
      }
      const additive = e.ctrlKey || e.metaKey
      // Ctrl 点击是「加/减选」，保持原来的行为；
      // 普通点击落在**已被选中的那一群里**时不塌缩选择——否则框选一堆节点后
      // 永远只能拖走手底下那一个，多选形同虚设。
      if (additive) store.select(id, true)
      else if (!selectionRef.current.includes(id)) store.select(id, false)

      const moving = resolveDragMove(rootTopic, id, useEditor.getState().selection)
      const group = moveRootsOf(moving).length

      /** 传给 `resolveDrop` 的「同时被拖的**其它**主题」（取参规则见 `alsoDraggedOf`） */
      const alsoDragged = alsoDraggedOf(moving, id)

      const movingIds = new Set(moving.ids)
      /**
       * 拖拽期间用来判断"插进同级空隙"的分组：把被拖的主题从分组里摘掉。
       * 否则指针压在自己那一层上时，会把落点算成"插进自己旁边"，
       * 画出一个根本不可能落下的提示（而且真正接纳它的父级也是错的）。
       */
      const dragStacks: SiblingStack[] = siblingStacks
        .filter((stack) => !movingIds.has(stack.parentId))
        .map((stack) => ({
          parentId: stack.parentId,
          children: stack.children.filter((child) => !movingIds.has(child.id))
        }))
        .filter((stack) => stack.children.length >= 2)

      const startX = e.clientX
      const startY = e.clientY
      let moved = false
      let plan: DropResult | null = null
      let side: 'left' | 'right' | null = null
      /** 本帧的非法落点原因（空串表示没有） */
      let blocked = ''

      /** 自动滚动的循环：只要这次拖拽还在，就持续按指针位置推动画布 */
      let scrollFrame = 0
      const tick = (): void => {
        dragAutoScroll()
        scrollFrame = window.requestAnimationFrame(tick)
      }
      const stopScroll = (): void => {
        if (scrollFrame) window.cancelAnimationFrame(scrollFrame)
        scrollFrame = 0
      }

      const onMove = (ev: PointerEvent): void => {
        const dx = ev.clientX - startX
        const dy = ev.clientY - startY
        if (!moved && Math.hypot(dx, dy) < 4) return
        moved = true
        // 自动滚动与松手时的落点都读这个位置，所以每帧都要更新
        pointerRef.current = { x: ev.clientX, y: ev.clientY, startX, startY }
        const z = zoomRef.current
        setDragVisual({ anchorId: id, dx: dx / z, dy: dy / z, moving, group })

        const world = screenToWorld(ev.clientX, ev.clientY)
        const rootTopic = rootRef.current
        const exclude = new Set(moving.ids)

        plan = null
        side = null
        // 按住 Alt ＝ 明确要求「自由摆放」：不吸附，位置随手放
        let free = ev.altKey

        if (!free) {
          /**
           * 指针是不是已经"挨着"某个主题了。挨着就**不允许**掉进自由摆放——
           * 那会把主题甩在树外面，自动布局随后把它搬去别处、连线横穿整张画布。
           */
          let adjacent = false

          // ① 先按「可吸附区域」找目标。区域是**分轴**外扩的：
          //    生长方向（子节点会待的那一侧）放宽，同级方向只留一点点。
          //    命中的候选里取离本体最近的——指针压在节点身上时距离为 0，自然优先。
          const nearby = dropCandidates.filter(
            (node) => !exclude.has(node.id) && distanceToRect(world, node.rect) <= SNAP_PREFILTER
          )
          const snap: SnapNode | null = nearestInRegion(
            nearby.map((node) => ({
              id: node.id,
              rect: node.rect,
              region: snapRegionOf(node.id) ?? node.rect,
              depth: node.depth
            })),
            world,
            exclude
          )
          if (snap) {
            adjacent = true
            // 语义仍交给 `zoneForPointer` / `resolveDrop`：
            // 沿同级方向贴前 / 贴后 → 插到它前 / 后；落回本体 → 成为它的子主题。
            // 目标是自己的父级时，`resolveDrop` 会正确地给出"原地不动"或"升一级"。
            const zone = zoneForPointer(snap.id, snap.rect, world)
            plan = resolveDrop(rootTopic, id, snap.id, zone, alsoDragged)
            // 挨着了却被裁决为非法：把**原因**写出来。否则用户看到的是"拖到这儿没反应"，
            // 只会以为软件坏了（"多选只能插同级"也是这一类）。
            if (!plan) blocked = blockReasonOf(rootTopic, id, snap.id, zone, alsoDragged)
          } else {
            // ② 区域没命中，再看是不是落在某两个同级主题**之间那条缝**里。
            //    缝比较宽时靠它兜底——区域本身只盖得住窄缝。
            const gap = nearestSiblingGap(dragStacks, world)
            if (gap) {
              adjacent = true
              plan = resolveDrop(rootTopic, id, gap.targetId, gap.mode, alsoDragged)
            }
            // ③ 再把一级主题拖到中心主题另一侧的情形认掉（那不是树上的落点）
            if (!plan) side = sideFlipTarget(world, id)
            // ④ 只有"什么都没挨着"才是自由摆放
            free = !plan && !side && !adjacent
          }
        }

        // 落点迟滞：换一个落点前，指针必须先走够一段距离。
        // 判定出结果后**只有一套**语义生效（plan / side / free 三者互斥），
        // 不会同时留下两个互相矛盾的预览。
        const freshKey = plan
          ? `${plan.targetId}|${plan.mode}`
          : side
            ? `side:${side}`
            : free
              ? 'free'
              : ''
        const latch = dropLatchRef.current
        // 迟滞按**屏幕像素**算：手感取决于"手走了多远"，与画布缩放无关。
        // 早先乘了缩放系数，放大时会异常黏、缩小时几乎失效。
        const withinHysteresis =
          Boolean(latch) &&
          Math.hypot(ev.clientX - (latch?.px ?? 0), ev.clientY - (latch?.py ?? 0)) <
            DROP_HYSTERESIS
        if (latch && latch.key !== freshKey && withinHysteresis) {
          // 还在迟滞半径里：保留上一次的裁决，不让提示在分界线上乱跳。
          // 空裁决（停在父级身上＝原地不动）也一起参与，否则提示会一闪一闪。
          plan = latch.plan
          side = latch.side
          free = latch.free
        } else if (freshKey) {
          dropLatchRef.current = {
            key: freshKey,
            plan,
            side,
            free,
            px: ev.clientX,
            py: ev.clientY
          }
        } else {
          dropLatchRef.current = null
        }

        dropPlanRef.current = plan
        setDropTarget(plan ? { id: plan.targetId, mode: plan.mode } : null)
        setDropLabel(group > 1 ? `${group} 个主题` : findTopic(rootTopic, id)?.title ?? '')
        setSideTarget(side)
        setFreeDrop(free)
        setDropBlocked(blocked)

        // 注意：落点是折叠主题时**不要在这里展开**。
        // 悬停就改数据，会让一次被 Esc 取消的拖拽也留下改动和撤销记录；
        // 展开改在真正落下时做，且和移动合并成同一笔（见 store 的 dropNode）。
      }

      const detach = (): void => {
        stopScroll()
        dropLatchRef.current = null
        window.removeEventListener('pointermove', onMove)
        window.removeEventListener('pointerup', onUp)
        window.removeEventListener('pointercancel', onCancel)
        window.removeEventListener('keydown', onKeyDown)
      }

      /** 指针被系统取消（例如切窗口）时只清理状态，不执行移动 */
      const onCancel = (): void => {
        detach()
        dropPlanRef.current = null
        setDragVisual(null)
        setDropTarget(null)
        setSideTarget(null)
        setFreeDrop(false)
        setDropBlocked('')
      }

      /** Esc 放弃这次拖拽：不动数据，把节点放回原处（Xmind 同款） */
      const onKeyDown = (ev: KeyboardEvent): void => {
        if (ev.key !== 'Escape') return
        ev.preventDefault()
        onCancel()
      }

      const onUp = (): void => {
        const active = plan
        const activeSide = side
        const startClient = pointerRef.current
        detach()
        dropPlanRef.current = null
        setDragVisual(null)
        setDropTarget(null)
        setSideTarget(null)
        setFreeDrop(false)
        setDropBlocked('')
        if (!moved || !startClient) return

        const worldDx = (startClient.x - startX) / zoomRef.current
        const worldDy = (startClient.y - startY) / zoomRef.current
        const state = useEditor.getState()

        if (active) {
          // 有落点就按落点走——注意落点也可能是"落在某两个节点中间的空隙里"，
          // 那种情况命中是空的但落点有值，不能当成自由摆放丢掉。
          // 多选拖拽只支持同级插入：成为某人的子主题无法同时满足一整群主题，
          // 会变成"只动了其中一个"，所以这种情况下落点本身就被裁决为非法。
          state.dropNode(id, active.targetId, active.mode)
          return
        }
        if (activeSide) {
          state.setTopicSide(id, activeSide)
          return
        }
        // 走到这里就是**自由摆放**（按住 Alt，或指针离最近的节点都很远）。
        // 只有真的动了才写：否则单击会凭空留下一条 0 位移的撤销记录。
        if (Math.abs(worldDx) < 1.5 && Math.abs(worldDy) < 1.5) return
        state.offsetPositions(
          moveRootsOf(moving).map((target) => ({ id: target, dx: worldDx, dy: worldDy }))
        )
      }

      window.addEventListener('pointermove', onMove)
      window.addEventListener('pointerup', onUp)
      window.addEventListener('pointercancel', onCancel)
      window.addEventListener('keydown', onKeyDown)
      scrollFrame = window.requestAnimationFrame(tick)
    },
    [
      screenToWorld,
      axesOf,
      zoneForPointer,
      snapRegionOf,
      siblingStacks,
      sideFlipTarget,
      dragAutoScroll,
      dropCandidates
    ]
  )

  /* ---- 拖动关系线的端点改接 ---- */
  const handleRelationshipPointerDown = useCallback(
    (
      e: ReactPointerEvent<SVGCircleElement>,
      relationshipId: string,
      end: 'end1Id' | 'end2Id',
      anchor: { x: number; y: number }
    ): void => {
      if (e.button !== 0) return
      // 必须阻止冒泡，否则画布会把这次按下当成「拖拽平移」
      e.stopPropagation()
      const store = useEditor.getState()
      if (store.editingId) store.commitEdit()

      const origin = screenToWorld(e.clientX, e.clientY)
      setHandleDrag({ relationshipId, end, anchor, pointer: origin, targetId: null })

      const onMove = (ev: PointerEvent): void => {
        const world = screenToWorld(ev.clientX, ev.clientY)
        setHandleDrag((current) =>
          current ? { ...current, pointer: world, targetId: hitTest(world.x, world.y) } : current
        )
      }
      const detach = (): void => {
        window.removeEventListener('pointermove', onMove)
        window.removeEventListener('pointerup', onUp)
        window.removeEventListener('pointercancel', onCancel)
      }
      const onCancel = (): void => {
        detach()
        setHandleDrag(null)
      }
      const onUp = (ev: PointerEvent): void => {
        detach()
        const world = screenToWorld(ev.clientX, ev.clientY)
        const target = hitTest(world.x, world.y)
        setHandleDrag(null)
        if (target) useEditor.getState().setRelationshipEnd(relationshipId, end, target)
      }

      window.addEventListener('pointermove', onMove)
      window.addEventListener('pointerup', onUp)
      window.addEventListener('pointercancel', onCancel)
    },
    [hitTest, screenToWorld]
  )

  /* ---- 双击标题就地编辑 ---- */
  const commitTitleEdit = useCallback((): void => {
    const target = titleEditRef.current
    if (!target) return
    if (cancelTitleRef.current) {
      cancelTitleRef.current = false
      setTitleEdit(null)
      return
    }
    const store = useEditor.getState()
    if (target.kind === 'boundary') store.setBoundaryTitle(target.id, target.value)
    else if (target.kind === 'summary') store.setSummaryTitle(target.id, target.value)
    else store.setRelationshipTitle(target.id, target.value)
    setTitleEdit(null)
  }, [])

  // 编辑过程中输入框的值是最新来源，用 ref 保证失焦提交读到的是最新内容
  const titleEditRef = useRef(titleEdit)
  titleEditRef.current = titleEdit

  /**
   * 落点预览，**两种落点各用一套、绝不混用**：
   *
   * - **成为子主题**（`child`）：画出被拖主题将要占据的**空位框**（实线、框里写标题、
   *   框下写「将成为子主题」），并从目标**子节点那一列**的边缘接一条实线过去。
   *   特意不从目标本体拉线：目标往往已有子节点，从它身上拉线会斜穿那些子节点，看着像连错。
   *
   * - **插到同级之间**（`before` / `after`）：只在目标与相邻兄弟之间画一条**短粗插入线**
   *   （Xmind / 知犀那套「插入位置条」）。不再画空位框，更不再把父级框起来——
   *   之前那套"父级琥珀框 + 远处一个大空位框"就是用户看到的自相矛盾提示。
   *
   * 方向轴全部由 `axesOf` / `zoneForPointer` 从实际坐标推出，不按结构名写特例。
   */
  const dropPreview = useMemo(() => {
    if (!dragVisual || !dropTarget) return null
    const dragged = layout.nodeMap.get(dragVisual.anchorId)
    const target = layout.nodeMap.get(dropTarget.id)
    if (!dragged || !target) return null

    const centerOf = (rect: DropRect): DropPoint => ({
      x: rect.x + rect.width / 2,
      y: rect.y + rect.height / 2
    })
    /** 从矩形中心朝某点看，求与矩形边框的交点——连线要接在边框上而不是中心 */
    const border = (rect: DropRect, toward: DropPoint): DropPoint => {
      const c = centerOf(rect)
      const dx = toward.x - c.x
      const dy = toward.y - c.y
      if (dx === 0 && dy === 0) return c
      const sx = dx === 0 ? Number.POSITIVE_INFINITY : rect.width / 2 / Math.abs(dx)
      const sy = dy === 0 ? Number.POSITIVE_INFINITY : rect.height / 2 / Math.abs(dy)
      const scale = Math.min(sx, sy)
      return { x: c.x + dx * scale, y: c.y + dy * scale }
    }

    const root = activeRoot(workbook)
    const pair = axesOf(dropTarget.id)
    const growth = growthAxis(pair)
    const color = branchColorOf(colors, layout, dropTarget.id)
    const title = dropLabel

    if (dropTarget.mode !== 'child') {
      // 同级插入：一条夹在"目标与相邻兄弟之间"的粗线（Xmind / 知犀那套"插入位置条"）。
      // 方向轴与 `zoneForPointer` 共用同一个 `insertAxis`，保证「线画在哪一侧、就插到哪一侧」。
      const direction = insertAxis(dropTarget.id, pair)
      const before = dropTarget.mode === 'before'
      // 线摆在哪一侧：after 摆朝前那一侧、before 摆朝后那一侧（线在两节点中间）
      const front = direction.forward === !before
      const pad = 10
      // 线的长度按**被拖主题**的尺寸来（而不是目标）：用户看到的应当是"我要占下多长一条位置"
      const span = Math.max(target.height, dragged.height) / 2 + pad
      const spanX = Math.max(target.width, dragged.width) / 2 + pad
      const bar =
        direction.axis === 'x'
          ? {
              x1: front ? target.x + target.width + 7 : target.x - 7,
              y1: centerOf(target).y - span,
              x2: front ? target.x + target.width + 7 : target.x - 7,
              y2: centerOf(target).y + span
            }
          : {
              x1: centerOf(target).x - spanX,
              y1: front ? target.y + target.height + 7 : target.y - 7,
              x2: centerOf(target).x + spanX,
              y2: front ? target.y + target.height + 7 : target.y - 7
            }
      return { kind: 'bar' as const, bar, color, title }
    }

    // 成为子主题：排在最后一个已有子节点之后
    const childRects: DropRect[] = []
    for (const child of findTopic(root, dropTarget.id)?.children ?? []) {
      const rect = layout.nodeMap.get(child.id)
      if (rect) childRects.push(rect)
    }
    const base = childRects[childRects.length - 1] ?? target
    // 空位框紧贴目标自己的列（gap 只留一点），不按普通兄弟间距摆——
    // 它要看起来像"这个主题新长出来的那一支"，而不是另起一列
    const gap = 12
    const slot: DropRect =
      growth.axis === 'x'
        ? {
            x: growth.forward ? base.x + base.width + gap : base.x - gap - dragged.width,
            y: base.y + base.height / 2 - dragged.height / 2,
            width: dragged.width,
            height: dragged.height
          }
        : {
            x: base.x + base.width / 2 - dragged.width / 2,
            y: growth.forward ? base.y + base.height + gap : base.y - gap - dragged.height,
            width: dragged.width,
            height: dragged.height
          }
    // 目标还没有子节点时，从目标朝生长方向的边框接出去；有子节点时从那一列接出去
    const origin: DropPoint =
      growth.axis === 'x'
        ? {
            x: growth.forward ? target.x + target.width + 10 : target.x - 10,
            y: centerOf(slot).y
          }
        : {
            x: centerOf(slot).x,
            y: growth.forward ? target.y + target.height + 10 : target.y - 10
          }

    return {
      kind: 'slot' as const,
      slot,
      from: origin,
      to: border(slot, origin),
      color,
      title
    }
  }, [dragVisual, dropTarget, dropLabel, layout, workbook, colors, axesOf, growthAxis, insertAxis])

  /** 左右对调的预览：把被拖的一级主题镜像到中心主题的另一侧 */
  const sideFlipPreview = useMemo(() => {
    if (!sideTarget || !dragVisual) return null
    const rootTopic = activeRoot(workbook)
    const rootRect = layout.nodeMap.get(rootTopic.id)
    const selfRect = layout.nodeMap.get(dragVisual.anchorId)
    if (!rootRect || !selfRect) return null
    const centerX = rootRect.x + rootRect.width / 2
    return {
      x: 2 * centerX - (selfRect.x + selfRect.width),
      y: selfRect.y,
      width: selfRect.width,
      height: selfRect.height,
      title: selfRect.topic.title,
      color: branchColorOf(colors, layout, dragVisual.anchorId)
    }
  }, [sideTarget, dragVisual, layout, workbook, colors])

  /**
   * 多选拖拽时在被抓的那个主题角上挂一个「N 个主题」的小徽标。
   * 一群人一起走的时候，光看透明度分不出到底拖走几个，
   * 有个数字就能立刻确认"这次拖的是不是我要的那几个"。
   */
  const groupBadge = useMemo(() => {
    if (!dragVisual || dragVisual.group <= 1) return null
    const anchor = layout.nodeMap.get(dragVisual.anchorId)
    if (!anchor) return null
    return {
      x: anchor.x + anchor.width + dragVisual.dx + 6,
      y: anchor.y + dragVisual.dy - 10,
      text: `${dragVisual.group} 个主题`
    }
  }, [dragVisual, layout])

  /** 选中画布元素（概要 / 边界 / 关系线）并打开属性面板：文字、字体、删除都在面板里 */
  const pickOverlay = useCallback(
    (event: ReactPointerEvent<SVGElement>, kind: 'summary' | 'boundary' | 'relationship', id: string): void => {
      event.stopPropagation()
      const store = useEditor.getState()
      store.selectOverlay(kind, id)
      store.requestNodePanel()
    },
    []
  )

  /* ---- 拖动关系线的线身：整体移动弧线（弯度偏移） ---- */
  const handleCurvePointerDown = useCallback((e: ReactPointerEvent<SVGPathElement>, relationshipId: string): void => {
    if (e.button !== 0) return
    e.stopPropagation()
    const store = useEditor.getState()
    // 点线身 = 选中这条关系线（顺手把属性面板打开），拖才改弯度：
    // 否则「点一下线上什么都没有发生」，看起来就像这条线选不中
    store.selectOverlay('relationship', relationshipId)
    store.requestNodePanel()
    if (store.editingId) store.commitEdit()

    let lastX = e.clientX
    let lastY = e.clientY

    const onMove = (ev: PointerEvent): void => {
      const z = zoomRef.current
      const dx = (ev.clientX - lastX) / z
      const dy = (ev.clientY - lastY) / z
      lastX = ev.clientX
      lastY = ev.clientY
      if (dx === 0 && dy === 0) return
      useEditor.getState().offsetRelationshipCurve(relationshipId, dx, dy)
    }
    const detach = (): void => {
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', onUp)
      window.removeEventListener('pointercancel', onUp)
    }
    const onUp = (): void => detach()

    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', onUp)
    window.addEventListener('pointercancel', onUp)
  }, [])

  /* ---- 空白处：右键/中键拖动平移；左键拖动框选 ---- */
  const handleBackgroundPointerDown = useCallback(
    (e: ReactPointerEvent<HTMLDivElement>): void => {
      const store = useEditor.getState()
      if (store.editingId) store.commitEdit()
      if (e.button !== 0 && e.button !== 1 && e.button !== 2) return

      // 与 Xmind 一致：右键（或中键）拖动平移画布
      if (e.button === 1 || e.button === 2) {
        e.preventDefault()
        const startX = e.clientX
        const startY = e.clientY
        const startPan = { ...panRef.current }
        const onMove = (ev: PointerEvent): void => {
          setPan({ x: startPan.x + (ev.clientX - startX), y: startPan.y + (ev.clientY - startY) })
        }
        const detach = (): void => {
          window.removeEventListener('pointermove', onMove)
          window.removeEventListener('pointerup', onUp)
          window.removeEventListener('pointercancel', onCancel)
        }
        const onCancel = (): void => detach()
        // 右键原地点击不应清空选择
        const onUp = (): void => detach()
        window.addEventListener('pointermove', onMove)
        window.addEventListener('pointerup', onUp)
        window.addEventListener('pointercancel', onCancel)
        return
      }

      // 左键：框选
      const rect = containerRef.current?.getBoundingClientRect()
      const baseLeft = rect?.left ?? 0
      const baseTop = rect?.top ?? 0
      const startClient = { x: e.clientX, y: e.clientY }
      const startLocal = { x: e.clientX - baseLeft, y: e.clientY - baseTop }
      let moved = false

      const onMove = (ev: PointerEvent): void => {
        const localX = ev.clientX - baseLeft
        const localY = ev.clientY - baseTop
        if (!moved && Math.hypot(localX - startLocal.x, localY - startLocal.y) < 3) return
        moved = true
        setMarquee({ x0: startLocal.x, y0: startLocal.y, x1: localX, y1: localY })
      }
      const detach = (): void => {
        window.removeEventListener('pointermove', onMove)
        window.removeEventListener('pointerup', onUp)
        window.removeEventListener('pointercancel', onCancel)
      }
      const onCancel = (): void => {
        detach()
        setMarquee(null)
      }
      const onUp = (ev: PointerEvent): void => {
        detach()
        setMarquee(null)
        const state = useEditor.getState()

        // 只是点了一下空白：取消选择
        if (!moved) {
          state.select(null)
          return
        }

        const z = zoomRef.current
        const pan = panRef.current
        const toWorld = (client: { x: number; y: number }): { x: number; y: number } => ({
          x: (client.x - baseLeft - pan.x) / z,
          y: (client.y - baseTop - pan.y) / z
        })
        const from = toWorld(startClient)
        const to = toWorld({ x: ev.clientX, y: ev.clientY })
        const minX = Math.min(from.x, to.x)
        const maxX = Math.max(from.x, to.x)
        const minY = Math.min(from.y, to.y)
        const maxY = Math.max(from.y, to.y)

        const hits = (layoutRef.current?.nodes ?? [])
          .filter(
            (node) =>
              node.x <= maxX &&
              node.x + node.width >= minX &&
              node.y <= maxY &&
              node.y + node.height >= minY
          )
          .map((node) => node.id)

        // 按住 Ctrl 拖动是「追加选择」
        const base = ev.ctrlKey || ev.metaKey ? state.selection : []
        state.setSelection([...base, ...hits])
      }

      window.addEventListener('pointermove', onMove)
      window.addEventListener('pointerup', onUp)
      window.addEventListener('pointercancel', onCancel)
    },
    [setPan]
  )

  /* ---- 视口裁剪：只渲染可见范围内的节点 ---- */
  const visibleNodes = useMemo(() => {
    if (size.width === 0 || size.height === 0) return layout.nodes
    const margin = 260 / zoom
    const x0 = -pan.x / zoom - margin
    const y0 = -pan.y / zoom - margin
    const x1 = (size.width - pan.x) / zoom + margin
    const y1 = (size.height - pan.y) / zoom + margin
    return layout.nodes.filter(
      (n) => n.id === editingId || (n.x + n.width >= x0 && n.x <= x1 && n.y + n.height >= y0 && n.y <= y1)
    )
  }, [layout, pan.x, pan.y, zoom, size.width, size.height, editingId])

  const visibleIds = useMemo(() => new Set(visibleNodes.map((n) => n.id)), [visibleNodes])

  /* ---- 搜索命中与筛选：面板与画布共用 store 里的同一份条件 ---- */
  const sheet = useMemo(() => activeSheet(workbook), [workbook])

  // 搜索词用防抖后的值：每敲一个键都要全树扫一遍，大文档下纯属白费
  const activeQuery = useDebouncedValue(search.query)

  const searchHits = useMemo(
    () =>
      activeQuery.trim().length > 0 ? hitTopicIds(searchSheet(sheet, activeQuery, search.options)) : null,
    [sheet, activeQuery, search.options]
  )

  const filterResult = useMemo(
    () => (isFilterActive(filter) ? applyTopicFilter(sheet.rootTopic, filter) : null),
    [sheet, filter]
  )

  /**
   * 连线裁剪：按**边的包围盒**（两端节点矩形的外接框，外扩余量）与视口求交。
   *
   * 之前按「两端节点是否可见」过滤——长连线的两端都被裁掉时，
   * 即使线身横穿屏幕中央，整条线也会凭空消失（用户报的"连线过长导致连线消失"）。
   */
  const visibleEdges = useMemo(() => {
    if (size.width === 0 || size.height === 0) return layout.edges
    const margin = 260 / zoom
    const x0 = -pan.x / zoom - margin
    const y0 = -pan.y / zoom - margin
    const x1 = (size.width - pan.x) / zoom + margin
    const y1 = (size.height - pan.y) / zoom + margin
    return layout.edges.filter((edge) => {
      const from = layout.nodeMap.get(edge.fromId)
      const to = layout.nodeMap.get(edge.toId)
      if (!from || !to) return false
      const ex0 = Math.min(from.x, to.x) - margin
      const ex1 = Math.max(from.x + from.width, to.x + to.width) + margin
      const ey0 = Math.min(from.y, to.y) - margin
      const ey1 = Math.max(from.y + from.height, to.y + to.height) + margin
      // 外接框与可见矩形相交才保留
      return ex1 >= x0 && ex0 <= x1 && ey1 >= y0 && ey0 <= y1
    })
  }, [layout.edges, layout.nodeMap, pan.x, pan.y, zoom, size.width, size.height])

  /**
   * 正在被拖拽的主题（多选时是一整群）连同它们的**整棵子树**。
   * 必须整棵一起移动：只挪自己会让子节点的连接线留在原地、看起来像断了一地。
   */
  const dragSet = useMemo(() => (dragVisual ? new Set(dragVisual.moving.ids) : null), [dragVisual])


  /**
   * 拖拽时把连线分成两拨：
   * - staticEdges：留在原地的那部分。其中「父节点 → 被拖节点」这条**特意去掉**，
   *   也就是视觉上把原来的连接断开；
   * - dragEdges：子树内部的连线，稍后跟着节点一起平移重画。
   */
  const staticEdges = useMemo(
    () => (dragSet ? visibleEdges.filter((edge) => !dragSet.has(edge.toId)) : visibleEdges),
    [visibleEdges, dragSet]
  )
  const dragEdges = useMemo(
    () =>
      dragSet
        ? visibleEdges.filter((edge) => dragSet.has(edge.toId) && dragSet.has(edge.fromId))
        : [],
    [visibleEdges, dragSet]
  )

  /** 画一条树上的连线。静态层与拖拽层共用，避免样式写两遍。 */
  const renderEdge = (edge: (typeof layout.edges)[number]): ReactElement => {
    const target = layout.nodeMap.get(edge.toId)
    const isFirstLevel = Boolean(target && target.depth === 1)
    return (
      <path
        key={`${edge.fromId}->${edge.toId}`}
        d={edge.d}
        fill="none"
        stroke={branchColorOf(colors, layout, edge.toId)}
        strokeWidth={isFirstLevel ? colors.edgeWidth * 1.5 : colors.edgeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        opacity={colors.edgeOpacity}
      />
    )
  }

  return (
    <div
      ref={containerRef}
      className="canvas"
      style={{
        backgroundColor: colors.canvas,
        backgroundImage: `radial-gradient(circle, ${colors.grid} 1px, transparent 1px)`
      }}
      onPointerDown={handleBackgroundPointerDown}
      /* 右键用于拖动平移，屏蔽系统右键菜单 */
      onContextMenu={(e) => e.preventDefault()}
    >
      <div
        className="canvas__world"
        style={{
          transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`,
          width: layout.bounds.width,
          height: layout.bounds.height
        }}
      >
        <svg className="canvas__edges" width={layout.bounds.width} height={layout.bounds.height}>
          {/* 结构专属的装饰线（时间轴主轴、鱼骨图主脊、括号图的括号） */}
          {layout.decorations.map((decoration, index) => (
            <path
              key={`deco-${index}`}
              d={decoration.d}
              fill="none"
              stroke={
                decoration.branchId
                  ? branchColorOf(colors, layout, decoration.branchId)
                  : colors.deepText
              }
              strokeWidth={colors.edgeWidth * (decoration.widthScale ?? 1)}
              strokeLinecap="round"
              strokeLinejoin="round"
              opacity={decoration.dashed ? 0.5 : colors.edgeOpacity}
              strokeDasharray={decoration.dashed ? '6 5' : undefined}
            />
          ))}

          {/* 边界：同色的多个边界拼成一条 path 一次性填充，
              所以重叠区域不会被半透明叠加成更深的颜色 */}
          {boundaryGroups.map((group) => (
            <path
              key={`boundary-fill-${group.color}`}
              d={group.d}
              fill={group.color}
              fillOpacity={0.08}
              fillRule="nonzero"
              stroke={group.color}
              strokeWidth={1.5}
              strokeOpacity={0.6}
            />
          ))}

          {/* 每个边界一个透明命中区：双击即可改标题。
              单独画是为了能分辨出点中的是哪一个（填充是按颜色合并的） */}
          {layout.boundaries.map((boundary) => (
            <path
              key={`boundary-hit-${boundary.id}`}
              className="overlay-boundary-hit"
              d={boundary.d}
              fill="transparent"
              onPointerDown={(event) => pickOverlay(event, 'boundary', boundary.id)}
              onDoubleClick={() =>
                setTitleEdit({
                  kind: 'boundary',
                  id: boundary.id,
                  x: boundary.label.x,
                  y: boundary.label.y,
                  anchor: 'start',
                  value: boundary.title ?? ''
                })
              }
            />
          ))}

          {/* 选中边界的虚线框（与概要一致：选中就能在面板里改文字与字体） */}
          {layout.boundaries.map((boundary) =>
            selectedOverlay?.kind === 'boundary' && selectedOverlay.id === boundary.id && boundary.bounds ? (
              <rect
                key={`boundary-selected-${boundary.id}`}
                className="overlay-selected"
                x={boundary.bounds.x - 5}
                y={boundary.bounds.y - 5}
                width={boundary.bounds.width + 10}
                height={boundary.bounds.height + 10}
                rx={6}
              />
            ) : null
          )}

          {/* 边界标题单独画，保证文字在填充之上 */}
          {layout.boundaries.map((boundary) => {
            const boundaryText = readOverlayTextStyle(boundary.style, { fontSize: 12, bold: true })
            return boundary.title ? (
              <text
                key={`boundary-title-${boundary.id}`}
                className="overlay-title"
                x={boundary.label.x}
                y={boundary.label.y}
                fontSize={boundaryText.fontSize}
                fontWeight={boundaryText.bold ? 700 : 400}
                fontStyle={boundaryText.italic ? 'italic' : undefined}
                fill={
                  boundaryText.color ??
                  (boundary.branchId
                    ? branchColorOf(colors, layout, boundary.branchId)
                    : colors.deepText)
                }
                dominantBaseline="middle"
                onPointerDown={(event) => pickOverlay(event, 'boundary', boundary.id)}
                onDoubleClick={() =>
                  setTitleEdit({
                    kind: 'boundary',
                    id: boundary.id,
                    x: boundary.label.x,
                    y: boundary.label.y,
                    anchor: 'start',
                    value: boundary.title ?? ''
                  })
                }
              >
                {/* 边界标题同样支持换行（自上而下排） */}
                {overlayTitleLines(boundary.title).map((line, index) => (
                  <tspan key={index} x={boundary.label.x} dy={index === 0 ? 0 : OVERLAY_TITLE_LINE_HEIGHT}>
                    {line.length > 0 ? line : '\u00A0'}
                  </tspan>
                ))}
              </text>
            ) : null
          })}

          {/* 概要：覆盖一组同级主题的大括号 + 概要文字。
              文字为空时也画占位文字与命中区——否则「把文字删空」之后就再也点不到它了 */}
          {layout.summaries.map((summary) => {
            const color = summary.branchId ? branchColorOf(colors, layout, summary.branchId) : colors.deepText
            const text = readOverlayTextStyle(summary.style, { fontSize: 13, bold: true })
            const selected = selectedOverlay?.kind === 'summary' && selectedOverlay.id === summary.id
            const labelSize = summary.labelSize ?? { width: 48, height: OVERLAY_TITLE_LINE_HEIGHT }
            const labelLeft =
              summary.anchor === 'start'
                ? summary.label.x
                : summary.anchor === 'end'
                  ? summary.label.x - labelSize.width
                  : summary.label.x - labelSize.width / 2
            const openEditor = (): void =>
              setTitleEdit({
                kind: 'summary',
                id: summary.id,
                x: summary.label.x,
                y: summary.label.y,
                anchor: summary.anchor,
                value: summary.title ?? ''
              })
            const pick = (event: ReactPointerEvent<SVGElement>): void =>
              pickOverlay(event, 'summary', summary.id)
            return (
              <g key={`summary-${summary.id}`}>
                <path
                  d={summary.d}
                  fill="none"
                  stroke={color}
                  strokeWidth={1.6}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeOpacity={0.75}
                />
                {/* 命中区：括号线（按描边命中）+ 文字块矩形（空文字时也能点到） */}
                <path
                  d={summary.d}
                  fill="none"
                  stroke="transparent"
                  strokeWidth={12}
                  className="overlay-hit"
                  onPointerDown={pick}
                  onDoubleClick={openEditor}
                />
                <rect
                  x={labelLeft - 3}
                  y={summary.label.y - labelSize.height / 2 - 3}
                  width={labelSize.width + 6}
                  height={labelSize.height + 6}
                  fill="transparent"
                  className="overlay-hit"
                  onPointerDown={pick}
                  onDoubleClick={openEditor}
                />
                <text
                  className="overlay-title"
                  x={summary.label.x}
                  y={summary.label.y}
                  fontSize={text.fontSize}
                  fontWeight={text.bold ? 700 : 400}
                  fontStyle={text.italic ? 'italic' : undefined}
                  fill={text.color ?? color}
                  textAnchor={summary.anchor}
                  dominantBaseline="middle"
                  /* 用画布色给文字描一圈边，即使压到别的内容上也读得清 */
                  stroke={colors.canvas}
                  strokeWidth={4}
                  paintOrder="stroke"
                  strokeLinejoin="round"
                  /* 空文字时用半透明占位，提示「双击可以输入」 */
                  opacity={summary.title ? 1 : 0.45}
                  pointerEvents="none"
                >
                  {summary.title
                    ? overlayTitleLines(summary.title).map((line, index, all) => (
                        <tspan
                          key={index}
                          x={summary.label.x}
                          dy={
                            index === 0
                              ? -(all.length - 1) * (OVERLAY_TITLE_LINE_HEIGHT / 2)
                              : OVERLAY_TITLE_LINE_HEIGHT
                          }
                        >
                          {line.length > 0 ? line : '\u00A0'}
                        </tspan>
                      ))
                    : '概要（双击输入）'}
                </text>
                {selected && summary.bounds ? (
                  <rect
                    className="overlay-selected"
                    x={summary.bounds.x - 5}
                    y={summary.bounds.y - 5}
                    width={summary.bounds.width + 10}
                    height={summary.bounds.height + 10}
                    rx={4}
                  />
                ) : null}
              </g>
            )
          })}

          {staticEdges.map(renderEdge)}

          {/* 子树内部的连线：跟着被拖的节点一起平移重画 */}
          {dragSet && dragVisual ? (
            <g transform={`translate(${dragVisual.dx} ${dragVisual.dy})`} opacity={0.9}>
              {dragEdges.map(renderEdge)}
            </g>
          ) : null}
        </svg>

        {/* 关系线线身的命中层：特意画在节点**下面**。
            否则那 18px 的透明命中区会压在上层，把经过线下方节点的拖拽操作抢走，
            表现为「某些节点怎么都拖不动」。 */}
        <svg className="canvas__overlay" width={layout.bounds.width} height={layout.bounds.height}>
          {layout.relationships.map((relationship) => (
            <path
              key={`hit-${relationship.id}`}
              className="overlay-curve"
              d={relationship.d}
              fill="none"
              stroke="transparent"
              strokeWidth={18}
              strokeLinecap="round"
              onPointerDown={(event) => handleCurvePointerDown(event, relationship.id)}
              onDoubleClick={(event) => {
                event.stopPropagation()
                useEditor.getState().resetRelationshipCurve(relationship.id)
              }}
            >
              <title>拖动可移动这条线；双击恢复自动弯度</title>
            </path>
          ))}
        </svg>

        {visibleNodes.map((node) => (
          <TopicNode
            key={node.id}
            node={node}
            layout={layout}
            colors={colors}
            selected={selection.includes(node.id)}
            editing={editingId === node.id}
            editingRich={editingId === node.id ? editingRich : null}
            highlight={
              dropTarget && dropTarget.mode === 'child' && dropTarget.id === node.id
                ? 'child'
                : dropTarget && dropTarget.mode !== 'child' && dropTarget.id === node.id
                  ? 'sibling'
                  : handleDrag?.targetId === node.id
                    ? 'child'
                    : null
            }
            dragged={Boolean(dragSet?.has(node.id))}
            draggable={node.depth > 0}
            searchHit={searchHits ? searchHits.has(node.id) : false}
            dimmed={filterResult ? !filterResult.keep.has(node.id) : false}
            dragOffset={
              dragVisual && dragSet?.has(node.id) ? { dx: dragVisual.dx, dy: dragVisual.dy } : null
            }
            dragPrimary={Boolean(dragVisual && dragVisual.anchorId === node.id)}
            onPointerDown={handleNodePointerDown}
            onDoubleClick={(id) => useEditor.getState().beginEdit(id)}
            onRichChange={(id, rich) => {
              const store = useEditor.getState()
              if (store.editingId === id) store.updateEditingRich(rich)
            }}
            onCancelEdit={() => useEditor.getState().cancelEdit()}
            onCommitEdit={() => useEditor.getState().commitEdit()}
            onCommitAndAddChild={() => useEditor.getState().commitAndAddChild()}
            onCommitAndAddSibling={() => useEditor.getState().commitAndAddSibling()}
            onNavigateEdit={(key) => {
              // 空主题上的方向键：先提交（空内容不会进撤销栈），再移动选择
              const store = useEditor.getState()
              if (store.editingId) store.commitEdit()
              store.navigateSelection(key)
            }}
            onToggleCollapse={(id) => useEditor.getState().toggleCollapse(id)}
          />
        ))}

        {/* 关系线画在节点之上，避免被节点挡住 */}
        <svg className="canvas__overlay" width={layout.bounds.width} height={layout.bounds.height}>
          {layout.relationships.map((relationship) => {
            const color = relationship.branchId
              ? branchColorOf(colors, layout, relationship.branchId)
              : colors.deepText
            const angle = ((relationship.arrow.angle * 180) / Math.PI).toFixed(1)
            // 标题那一小块就是这条线的可选中区域（空标题也给一块，否则选不中）
            const size = relationship.labelSize ?? { width: 24, height: 16 }
            const labelBox = {
              x: relationship.label.x - size.width / 2 - 4,
              y: relationship.label.y - size.height / 2 - 4,
              width: size.width + 8,
              height: size.height + 8
            }
            const active =
              selectedOverlay?.kind === 'relationship' && selectedOverlay.id === relationship.id
            return (
              <g key={`relationship-${relationship.id}`}>
                <path d={relationship.d} fill="none" stroke={color} strokeWidth={1.8} strokeLinecap="round" />
                {/* 线身的可拖拽命中区在节点下面那一层，见上方 canvas__overlay 命中层 */}

                <path
                  d="M 0 0 L -10 -4 L -10 4 Z"
                  transform={`translate(${relationship.arrow.x} ${relationship.arrow.y}) rotate(${angle})`}
                  fill={color}
                />

                {/* 标题区的透明命中区：单击选中、双击改文字 */}
                <rect
                  className="overlay-hit"
                  x={labelBox.x}
                  y={labelBox.y}
                  width={labelBox.width}
                  height={labelBox.height}
                  rx={4}
                  fill="transparent"
                  onPointerDown={(event) => pickOverlay(event, 'relationship', relationship.id)}
                  onDoubleClick={() =>
                    setTitleEdit({
                      kind: 'relationship',
                      id: relationship.id,
                      x: relationship.label.x,
                      y: relationship.label.y,
                      anchor: 'middle',
                      value: relationship.title ?? ''
                    })
                  }
                />
                {active ? (
                  <rect
                    className="overlay-selected"
                    x={labelBox.x}
                    y={labelBox.y}
                    width={labelBox.width}
                    height={labelBox.height}
                    rx={4}
                  />
                ) : null}

                {relationship.title ? (
                  <text
                    className="overlay-title"
                    x={relationship.label.x}
                    y={relationship.label.y}
                    fontSize={12}
                    fontWeight={600}
                    fill={color}
                    textAnchor="middle"
                    dominantBaseline="middle"
                    stroke={colors.canvas}
                    strokeWidth={4}
                    paintOrder="stroke"
                    strokeLinejoin="round"
                    pointerEvents="none"
                  >
                    {relationship.title}
                  </text>
                ) : null}

                {/* 两端各一个手柄：拖到别的主题上即可改接这一端 */}
                {(
                  [
                    { end: 'end1Id' as const, point: relationship.start },
                    { end: 'end2Id' as const, point: relationship.arrow }
                  ] as const
                ).map((handle) => (
                  <circle
                    key={`${relationship.id}-${handle.end}`}
                    className={
                      handleDrag &&
                      handleDrag.relationshipId === relationship.id &&
                      handleDrag.end === handle.end
                        ? 'overlay-handle overlay-handle--active'
                        : 'overlay-handle'
                    }
                    cx={handle.point.x}
                    cy={handle.point.y}
                    r={7}
                    fill={color}
                    onPointerDown={(event) =>
                      handleRelationshipPointerDown(event, relationship.id, handle.end, handle.point)
                    }
                  >
                    <title>拖到另一个主题上可改接这一端</title>
                  </circle>
                ))}
              </g>
            )
          })}

          {/* 落点预览：要么是"成为子主题"的空位框，要么是"插到同级之间"的插入线 */}
          {dropPreview && dropPreview.kind === 'slot' ? (
            <g>
              <line
                x1={dropPreview.from.x}
                y1={dropPreview.from.y}
                x2={dropPreview.to.x}
                y2={dropPreview.to.y}
                stroke={dropPreview.color}
                strokeWidth={1.8}
                /* 用实线 —— 那就是这个主题将来真正的那条连线，虚线会让人以为"还没连上" */
                strokeLinecap="round"
                opacity={0.9}
              />
              <rect
                x={dropPreview.slot.x}
                y={dropPreview.slot.y}
                width={dropPreview.slot.width}
                height={dropPreview.slot.height}
                rx={10}
                fill={dropPreview.color}
                fillOpacity={0.14}
                stroke={dropPreview.color}
                strokeWidth={2}
              />
              {/* 空位框里写上"是谁要落到这里"，比只显示一个空格子清楚得多 */}
              {dropPreview.title ? (
                <text
                  x={dropPreview.slot.x + dropPreview.slot.width / 2}
                  y={dropPreview.slot.y + dropPreview.slot.height / 2}
                  fontSize={12}
                  fontWeight={600}
                  fill={dropPreview.color}
                  textAnchor="middle"
                  dominantBaseline="middle"
                >
                  {clipText(dropPreview.title, dropPreview.slot.width)}
                </text>
              ) : null}
              {/* 成为子主题这件事光看几何位置不够直观，直接在空位框下写明 */}
              <text
                x={dropPreview.slot.x + dropPreview.slot.width / 2}
                y={dropPreview.slot.y + dropPreview.slot.height + 14}
                fontSize={11}
                fontWeight={700}
                fill={dropPreview.color}
                textAnchor="middle"
                dominantBaseline="middle"
                stroke={colors.canvas}
                strokeWidth={4}
                paintOrder="stroke"
                strokeLinejoin="round"
              >
                将成为子主题
              </text>
            </g>
          ) : null}

          {/*
            同级插入：只画一条夹在目标与相邻兄弟之间的粗插入线（Xmind / 知犀那套"插入位置条"）。
            位置紧贴目标外缘，就在指针附近，不会像过去的空位框那样跑到很远的父级那边去。
          */}
          {dropPreview && dropPreview.kind === 'bar' ? (
            <g>
              <line
                x1={dropPreview.bar.x1}
                y1={dropPreview.bar.y1}
                x2={dropPreview.bar.x2}
                y2={dropPreview.bar.y2}
                stroke={dropPreview.color}
                strokeWidth={5}
                strokeLinecap="round"
              />
              <circle
                cx={(dropPreview.bar.x1 + dropPreview.bar.x2) / 2}
                cy={(dropPreview.bar.y1 + dropPreview.bar.y2) / 2}
                r={4.5}
                fill="#ffffff"
                stroke={dropPreview.color}
                strokeWidth={2.5}
              />
            </g>
          ) : null}

          {/* 左右对调的预览：镜像到中心主题另一侧 */}
          {sideFlipPreview ? (
            <g>
              <rect
                x={sideFlipPreview.x}
                y={sideFlipPreview.y}
                width={sideFlipPreview.width}
                height={sideFlipPreview.height}
                rx={10}
                fill={sideFlipPreview.color}
                fillOpacity={0.08}
                stroke={sideFlipPreview.color}
                strokeWidth={1.5}
                strokeDasharray="6 5"
              />
              {sideFlipPreview.title ? (
                <text
                  x={sideFlipPreview.x + sideFlipPreview.width / 2}
                  y={sideFlipPreview.y + sideFlipPreview.height / 2}
                  fontSize={12}
                  fontWeight={600}
                  fill={sideFlipPreview.color}
                  textAnchor="middle"
                  dominantBaseline="middle"
                >
                  {clipText(sideFlipPreview.title, sideFlipPreview.width)}
                </text>
              ) : null}
            </g>
          ) : null}

          {/* 多选拖拽：角上挂一个「N 个主题」的徽标 */}
          {groupBadge ? (
            <g>
              <rect
                x={groupBadge.x}
                y={groupBadge.y}
                width={groupBadge.text.length * 11 + 14}
                height={22}
                rx={11}
                fill="#f59e0b"
              />
              <text
                x={groupBadge.x + (groupBadge.text.length * 11 + 14) / 2}
                y={groupBadge.y + 11}
                fontSize={12}
                fontWeight={700}
                fill="#ffffff"
                textAnchor="middle"
                dominantBaseline="middle"
              >
                {groupBadge.text}
              </text>
            </g>
          ) : null}

          {/* 拖拽端点时的预览线 */}
          {handleDrag ? (
            <line
              x1={handleDrag.anchor.x}
              y1={handleDrag.anchor.y}
              x2={handleDrag.pointer.x}
              y2={handleDrag.pointer.y}
              stroke={colors.deepText}
              strokeWidth={1.6}
              strokeDasharray="6 5"
              strokeLinecap="round"
              opacity={0.7}
            />
          ) : null}
        </svg>

        {/* 双击标题后的就地编辑框。放在世界容器内，所以会随画布一起缩放。
            概要支持换行，用 textarea（Enter 换行、Esc 取消、失焦提交）；其余仍是单行 input */}
        {titleEdit && titleEdit.kind === 'summary' ? (
          <textarea
            className="overlay-title-editor overlay-title-editor--multi"
            rows={Math.max(1, overlayTitleLines(titleEdit.value).length)}
            style={{
              left: titleEdit.x,
              top: titleEdit.y - 13,
              transform:
                titleEdit.anchor === 'middle'
                  ? 'translateX(-50%)'
                  : titleEdit.anchor === 'end'
                    ? 'translateX(-100%)'
                    : 'none'
            }}
            value={titleEdit.value}
            autoFocus
            onFocus={(e) => e.currentTarget.select()}
            onChange={(e) => {
              const next = e.currentTarget.value
              setTitleEdit((current) => (current ? { ...current, value: next } : current))
            }}
            onPointerDown={(e) => e.stopPropagation()}
            onKeyDown={(e) => {
              e.stopPropagation()
              if (e.nativeEvent.isComposing || e.keyCode === 229) return
              // Enter 交给 textarea 换行；Esc 取消并提交（走失焦那条统一路径）
              if (e.key === 'Escape') {
                e.preventDefault()
                cancelTitleRef.current = true
                e.currentTarget.blur()
              }
            }}
            onBlur={commitTitleEdit}
          />
        ) : titleEdit ? (
          <input
            className="overlay-title-editor"
            style={{
              left: titleEdit.x,
              top: titleEdit.y - 13,
              transform:
                titleEdit.anchor === 'middle'
                  ? 'translateX(-50%)'
                  : titleEdit.anchor === 'end'
                    ? 'translateX(-100%)'
                    : 'none'
            }}
            value={titleEdit.value}
            autoFocus
            onFocus={(e) => e.currentTarget.select()}
            onChange={(e) => {
              const next = e.currentTarget.value
              setTitleEdit((current) => (current ? { ...current, value: next } : current))
            }}
            onPointerDown={(e) => e.stopPropagation()}
            onKeyDown={(e) => {
              e.stopPropagation()
              // 输入法组词期间交给输入法处理（React 合成事件没有 isComposing）
              if (e.nativeEvent.isComposing || e.keyCode === 229) return
              if (e.key === 'Enter' || e.key === 'Escape') {
                e.preventDefault()
                // 统一交给失焦处理，避免「回车提交」和「失焦提交」各写一次
                if (e.key === 'Escape') cancelTitleRef.current = true
                e.currentTarget.blur()
              }
            }}
            onBlur={commitTitleEdit}
          />
        ) : null}
      </div>

      {/* 拖到真正的空白处：明确告诉用户"这一下会自由摆放"，
          免得他以为已经吸附进树里了（自由摆放的主题会被自动布局甩在一边，连线横穿整张图） */}
      {/* 常驻图例：拖拽的三种结果提前讲清楚，不用用户去试 */}
      <div className="canvas__drag-legend">
        <span className={dragVisual && dropTarget?.mode === 'child' ? 'is-active' : undefined}>
          拖到主题上＝成为子主题
        </span>
        <span className="canvas__drag-legend-sep">·</span>
        <span
          className={dragVisual && dropTarget && dropTarget.mode !== 'child' ? 'is-active' : undefined}
        >
          拖到同级之间＝插进那一层
        </span>
        <span className="canvas__drag-legend-sep">·</span>
        <span className={dragVisual && freeDrop ? 'is-active' : undefined}>按住 Alt＝自由摆放</span>
      </div>

      {freeDrop ? <div className="canvas__free-hint">自由摆放（按住 Alt 可随时切换）</div> : null}

      {/* 落点被判为非法的原因：不写出来，用户只会以为"拖到这里没反应"＝坏了 */}
      {dropBlocked ? <div className="canvas__blocked-hint">{dropBlocked}</div> : null}

      {/* 左键框选的橡皮筋 */}
      {marquee ? (
        <div
          className="canvas__marquee"
          style={{
            left: Math.min(marquee.x0, marquee.x1),
            top: Math.min(marquee.y0, marquee.y1),
            width: Math.abs(marquee.x1 - marquee.x0),
            height: Math.abs(marquee.y1 - marquee.y0)
          }}
        />
      ) : null}
    </div>
  )
}

import { useCallback, useEffect, useState, type ReactElement } from 'react'
import {
  Camera,
  Clock,
  FolderOpen,
  History as HistoryIcon,
  Pin,
  PinOff,
  RotateCcw,
  Star,
  Trash2,
  X
} from 'lucide-react'
import { relativeTime, type HistoryEntry } from '@shared/history'
import {
  formatBytes,
  snapshotLabel,
  snapshotReasonLabel,
  type SnapshotItem,
  type SnapshotReason
} from '@shared/snapshot'
import { defaultDocumentName } from '@shared/model/naming'
import { snapshotForSave, useEditor } from '../store/editor'
import { activeDocId } from '../store/tabs'
import { Modal } from './Dialogs'

interface Props {
  onClose(): void
  onNotify(message: string): void
  /** 打开某个历史文件（由 App 负责走「未保存确认 → 打开」的完整流程） */
  onOpenFile(path: string): void
  /** 恢复某个版本（由 App 负责「先存一份恢复前版本 → 再恢复」） */
  onRestore(snapshotId: string): void
}

type Tab = 'files' | 'snapshots'

const REASON_CLASS: Record<SnapshotReason, string> = {
  auto: 'snapshot-badge--auto',
  manual: 'snapshot-badge--manual',
  'before-restore': 'snapshot-badge--restore'
}

/**
 * 历史记录。
 *
 * 两个标签页解决两件不同的事：
 * - 「打开历史」：最近用过哪些文件（含常用与默认保存位置）
 * - 「版本快照」：**当前这份文档**在不同时间点的内容版本，可随时切回
 *
 * 版本列表由本组件自己读写（只需要路径与会话序号），
 * 只有「恢复」交给 App —— 那一步要走未保存确认，还要先自动存一份恢复前的版本。
 */
export default function HistoryDialog({ onClose, onNotify, onOpenFile, onRestore }: Props): ReactElement {
  const filePath = useEditor((s) => s.filePath)

  const [tab, setTab] = useState<Tab>('files')

  const [entries, setEntries] = useState<HistoryEntry[]>([])
  const [saveDir, setSaveDir] = useState('')
  const [loading, setLoading] = useState(true)
  const [confirmClear, setConfirmClear] = useState(false)

  const [snapshots, setSnapshots] = useState<SnapshotItem[]>([])
  const [snapshotLoading, setSnapshotLoading] = useState(true)
  const [noteDraft, setNoteDraft] = useState('')
  const [busy, setBusy] = useState(false)
  const [confirmClearSnapshots, setConfirmClearSnapshots] = useState(false)

  /* ---- 打开历史 ---- */

  const refreshHistory = useCallback(async (): Promise<void> => {
    try {
      const [list, dir] = await Promise.all([window.api.historyList(), window.api.historySaveDir()])
      setEntries(list)
      setSaveDir(dir)
    } catch (error) {
      onNotify(`读取历史失败：${(error as Error).message}`)
    } finally {
      setLoading(false)
    }
  }, [onNotify])

  useEffect(() => {
    void refreshHistory()
  }, [refreshHistory])

  /* ---- 版本快照 ---- */

  const refreshSnapshots = useCallback(async (): Promise<void> => {
    try {
      setSnapshots(await window.api.snapshotList(filePath))
    } catch (error) {
      onNotify(`读取版本失败：${(error as Error).message}`)
    } finally {
      setSnapshotLoading(false)
    }
  }, [filePath, onNotify])

  useEffect(() => {
    void refreshSnapshots()
  }, [refreshSnapshots])

  const pinned = entries.filter((entry) => entry.pinned)
  const recent = entries.filter((entry) => !entry.pinned)

  const act = async (run: () => Promise<HistoryEntry[]>, failText: string): Promise<void> => {
    try {
      setEntries(await run())
    } catch (error) {
      onNotify(`${failText}：${(error as Error).message}`)
    }
  }

  const chooseDir = async (): Promise<void> => {
    try {
      const dir = await window.api.historyChooseSaveDir()
      if (!dir) return
      setSaveDir(dir)
      onNotify(`默认保存位置已改为：${dir}`)
    } catch (error) {
      onNotify(`选择目录失败：${(error as Error).message}`)
    }
  }

  const createVersion = async (): Promise<void> => {
    if (busy || !filePath) return
    setBusy(true)
    try {
      const store = useEditor.getState()
      const note = noteDraft.trim()
      const list = await window.api.snapshotCreate(activeDocId(), {
        // 用「把正在输入的内容也算上」的快照，避免刚敲的字没进版本
        workbook: snapshotForSave(store),
        path: store.filePath,
        title: defaultDocumentName(store.workbook),
        reason: 'manual',
        note
      })
      setSnapshots(list)
      setNoteDraft('')
      onNotify(note.length > 0 ? `已存为版本：${note}` : '已存为一个版本')
    } catch (error) {
      onNotify(`存版本失败：${(error as Error).message}`)
    } finally {
      setBusy(false)
    }
  }

  const removeVersion = async (id: string): Promise<void> => {
    try {
      setSnapshots(await window.api.snapshotRemove(id, filePath))
      onNotify('已删除该版本')
    } catch (error) {
      onNotify(`删除失败：${(error as Error).message}`)
    }
  }

  const clearVersions = async (): Promise<void> => {
    if (!confirmClearSnapshots) {
      setConfirmClearSnapshots(true)
      return
    }
    setConfirmClearSnapshots(false)
    try {
      setSnapshots(await window.api.snapshotClear(filePath))
      onNotify('已清空本文档的版本')
    } catch (error) {
      onNotify(`清空失败：${(error as Error).message}`)
    }
  }

  /* ---- 渲染 ---- */

  const fileRow = (entry: HistoryEntry): ReactElement => (
    <div key={entry.path} className={entry.missing ? 'history-row history-row--missing' : 'history-row'}>
      <button
        type="button"
        className="history-row__main"
        title={entry.missing ? '文件已不在原位置' : `打开 ${entry.path}`}
        onMouseDown={(event) => event.preventDefault()}
        onClick={() => {
          if (entry.missing) {
            onNotify('这个文件已不在原位置：可能被移动或删除了，可以从列表里移除它')
            return
          }
          onOpenFile(entry.path)
          onClose()
        }}
      >
        <span className="history-row__name">
          {entry.pinned ? <Star size={12} className="history-row__star" /> : null}
          {entry.title && entry.title.length > 0 ? entry.title : entry.name}
        </span>
        <span className="history-row__meta">
          {entry.missing ? '⚠ 已不在原位置 · ' : ''}
          {relativeTime(entry.openedAt)}
          {entry.openCount > 1 ? ` · 打开过 ${entry.openCount} 次` : ''}
          {' · '}
          <span className="history-row__path">{entry.path}</span>
        </span>
      </button>

      <button
        type="button"
        className="chip__del"
        title={entry.pinned ? '取消常用' : '设为常用'}
        onMouseDown={(event) => event.preventDefault()}
        onClick={() => void act(() => window.api.historyTogglePin(entry.path), '操作失败')}
      >
        {entry.pinned ? <PinOff size={12} /> : <Pin size={12} />}
      </button>
      <button
        type="button"
        className="chip__del"
        title="在文件夹中显示"
        onMouseDown={(event) => event.preventDefault()}
        onClick={() => void window.api.revealInFolder(entry.path)}
      >
        <FolderOpen size={12} />
      </button>
      <button
        type="button"
        className="chip__del"
        title="从历史中移除"
        onMouseDown={(event) => event.preventDefault()}
        onClick={() => void act(() => window.api.historyRemove(entry.path), '移除失败')}
      >
        <X size={12} />
      </button>
    </div>
  )

  const versionRow = (item: SnapshotItem): ReactElement => (
    <div key={item.id} className="snapshot-row">
      <div className="snapshot-row__main">
        <span className="snapshot-row__name">
          <span className={`snapshot-badge ${REASON_CLASS[item.reason]}`}>
            {snapshotReasonLabel(item.reason)}
          </span>
          {snapshotLabel(item)}
        </span>
        <span className="snapshot-row__meta">
          {relativeTime(item.at)} · {formatBytes(item.size)}
          {item.path ? ` · ${item.path}` : ' · 当时还没保存过'}
        </span>
      </div>
      <button
        type="button"
        className="snapshot-row__act"
        title="恢复到这个版本（恢复前会自动把当前状态也存成一个版本，可再切回）"
        onMouseDown={(event) => event.preventDefault()}
        onClick={() => {
          onClose()
          onRestore(item.id)
        }}
      >
        <RotateCcw size={13} />
        恢复
      </button>
      <button
        type="button"
        className="chip__del"
        title="删除这个版本"
        onMouseDown={(event) => event.preventDefault()}
        onClick={() => void removeVersion(item.id)}
      >
        <X size={12} />
      </button>
    </div>
  )

  return (
    <Modal
      title="历史记录"
      icon={<HistoryIcon size={18} />}
      onMaskClick={onClose}
      footer={
        <>
          {tab === 'files' ? (
            <button
              type="button"
              className="btn btn--danger"
              disabled={entries.length === 0}
              onClick={() => {
                if (!confirmClear) {
                  setConfirmClear(true)
                  return
                }
                setConfirmClear(false)
                void act(() => window.api.historyClear(), '清空失败')
              }}
            >
              <Trash2 size={14} />
              {confirmClear ? '再点一次确认清空' : '清空历史'}
            </button>
          ) : (
            <button
              type="button"
              className="btn btn--danger"
              disabled={snapshots.length === 0}
              onClick={() => void clearVersions()}
            >
              <Trash2 size={14} />
              {confirmClearSnapshots ? '再点一次确认清空' : '清空本文档的版本'}
            </button>
          )}
          <button type="button" className="btn btn--primary" onClick={onClose}>
            关闭
          </button>
        </>
      }
    >
      <div className="hist-tabs">
        <button
          type="button"
          className={tab === 'files' ? 'hist-tab hist-tab--active' : 'hist-tab'}
          onClick={() => setTab('files')}
        >
          打开历史
          <em>{entries.length}</em>
        </button>
        <button
          type="button"
          className={tab === 'snapshots' ? 'hist-tab hist-tab--active' : 'hist-tab'}
          onClick={() => setTab('snapshots')}
        >
          <Camera size={13} />
          版本快照
          <em>{snapshots.length}</em>
        </button>
      </div>

      <div className="history-form">
        {tab === 'files' ? (
          <>
            <div className="history-dir">
              <span className="history-dir__label">默认保存位置</span>
              <span className="history-dir__path" title={saveDir}>
                {saveDir || '（未设置）'}
              </span>
              <button type="button" className="btn" onClick={() => void chooseDir()}>
                <FolderOpen size={14} />
                更换
              </button>
              <button
                type="button"
                className="btn"
                disabled={saveDir.length === 0}
                onClick={() => void window.api.revealInFolder(saveDir)}
              >
                打开文件夹
              </button>
            </div>

            {loading ? (
              <div className="history-empty">正在读取…</div>
            ) : entries.length === 0 ? (
              <div className="history-empty">
                <Clock size={16} />
                <span>还没有历史记录。打开或保存过 .xmind 之后，这里会列出最近用过的文件。</span>
              </div>
            ) : (
              <>
                <div className="side-panel__title">
                  <Star size={12} /> 常用（{pinned.length}）
                </div>
                {pinned.length === 0 ? (
                  <div className="history-hint">
                    点列表右侧的图钉按钮，可以把常用的导图固定到这里——固定的条目不会被后来的记录挤掉。
                  </div>
                ) : (
                  <div className="history-list">{pinned.map(fileRow)}</div>
                )}

                <div className="side-panel__title side-panel__title--sub">
                  <Clock size={12} /> 最近打开（{recent.length}）
                </div>
                {recent.length === 0 ? (
                  <div className="history-hint">暂无最近打开的文件。</div>
                ) : (
                  <div className="history-list">{recent.map(fileRow)}</div>
                )}
              </>
            )}
          </>
        ) : !filePath ? (
          <div className="history-empty history-empty--top">
            <Camera size={16} />
            <span>
              这份文档还没有保存过，暂时没有版本记录。
              <br />
              先按 <b>Ctrl+S</b> 存成 .xmind 文件，之后编辑过程中就会自动累积版本。
              <br />
              未保存的内容另有保护：每 30 秒自动存档，异常退出后下次启动会提示恢复。
            </span>
          </div>
        ) : (
          <>
            <div className="snapshot-create">
              <input
                className="input input--mini"
                placeholder="给这个版本写个备注（可留空）"
                value={noteDraft}
                onChange={(event) => setNoteDraft(event.target.value)}
                onKeyDown={(event) => {
                  if (event.key === 'Enter') void createVersion()
                }}
              />
              <button
                type="button"
                className="btn btn--primary"
                disabled={busy}
                onMouseDown={(event) => event.preventDefault()}
                onClick={() => void createVersion()}
              >
                <Camera size={14} />
                存一个版本
              </button>
            </div>

            <div className="history-hint">
              每 <b>10 分钟</b>会自动留一个版本（内容没变就跳过，不占地方）；
              手动存的版本不会被自动版本挤掉。恢复前也会自动存一份当前状态，<b>点错了还能切回来</b>。
            </div>

            {snapshotLoading ? (
              <div className="history-empty">正在读取…</div>
            ) : snapshots.length === 0 ? (
              <div className="history-empty">
                <Camera size={16} />
                <span>
                  这份文档还没有版本记录。可以先点「存一个版本」手动留一个，
                  之后编辑过程中也会自动累积。
                </span>
              </div>
            ) : (
              <div className="history-list">{snapshots.map(versionRow)}</div>
            )}
          </>
        )}
      </div>
    </Modal>
  )
}

import { useEffect, useMemo, useRef, useState, type ReactElement } from 'react'
import {
  Bold,
  Code2,
  Download,
  Eraser,
  ExternalLink,
  FolderOpen,
  Image as ImageIcon,
  Italic,
  Paperclip,
  Plus,
  Sigma,
  X
} from 'lucide-react'
import { activeRoot, activeSheet, findTopic } from '@shared/model/tree'
import { imageBoxSize } from '@shared/layout/accessory'
import { MARKER_GROUPS, markerVisualOf } from '../render/markers'
import { formulaHtml } from '../render/formula'
import { resourceUrl } from '../render/resource'
import { useEditor } from '../store/editor'
import { activeDocId } from '../store/tabs'
import MarkerIcon from './MarkerIcon'
import { CODE_LANGUAGES } from '@shared/code-language'
import { readOverlayTextStyle, type OverlayKind } from '@shared/model/overlay-style'

/** 画布元素标题的字体控制（与主题的格式栏同一套观感） */
const OVERLAY_FONT_SIZES = [12, 13, 14, 16, 18, 22, 28]
const OVERLAY_COLORS = ['#1f2328', '#EB5757', '#F2994A', '#27AE60', '#2D9CDB', '#2F6BFF', '#9B51E0']

/** 新建代码块的默认语言：来自「默认样式」面板的设置（null = 纯文本） */
function defaultCodeLanguage(): string {
  return useEditor.getState().appSettings.defaultCodeLanguage || 'text'
}
import { normalizeFormulaInput } from '@shared/formula'

interface Props {
  onClose(): void
  onNotify(message: string): void
}

/** 附件大小显示成 KB/MB，列表里一眼能看出体积 */
function formatSize(bytes: number | undefined): string {
  if (!bytes || bytes <= 0) return ''
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`
}

/** 备注与超链接用本地草稿 + 失焦提交：既不怕输入法打断，也不需要每敲一个字就写历史 */
export default function NodePanel({ onClose, onNotify }: Props): ReactElement {
  const workbook = useEditor((s) => s.workbook)
  const selection = useEditor((s) => s.selection)
  const toggleMarker = useEditor((s) => s.toggleMarker)
  const addLabel = useEditor((s) => s.addLabel)
  const removeLabel = useEditor((s) => s.removeLabel)
  const setNotes = useEditor((s) => s.setNotes)
  const setHref = useEditor((s) => s.setHref)
  const setFormula = useEditor((s) => s.setFormula)
  const setCode = useEditor((s) => s.setCode)
  const setSizeOverride = useEditor((s) => s.setSizeOverride)
  const codeFocusTick = useEditor((s) => s.codeFocusTick)
  const formulaFocusTick = useEditor((s) => s.formulaFocusTick)
  const setImage = useEditor((s) => s.setImage)
  const addAttachment = useEditor((s) => s.addAttachment)
  const removeAttachment = useEditor((s) => s.removeAttachment)
  const removeRelationship = useEditor((s) => s.removeRelationship)
  const removeBoundary = useEditor((s) => s.removeBoundary)
  const removeSummary = useEditor((s) => s.removeSummary)
  const setRelationshipTitle = useEditor((s) => s.setRelationshipTitle)
  const setBoundaryTitle = useEditor((s) => s.setBoundaryTitle)
  const setSummaryTitle = useEditor((s) => s.setSummaryTitle)

  const sheet = useMemo(() => activeSheet(workbook), [workbook])

  const id = selection[0] ?? null
  const topic = useMemo(() => (id ? findTopic(activeRoot(workbook), id) : null), [workbook, id])

  // 选中的是画布级元素（概要 / 边界 / 关系线）：它也有文字与字体，照样能改
  const selectedOverlay = useEditor((s) => s.selectedOverlay)
  const setOverlayStyle = useEditor((s) => s.setOverlayStyle)
  const overlayItem = useMemo(() => {
    const target = selectedOverlay
    if (!target) return null
    const list =
      target.kind === 'summary'
        ? sheet.summaries
        : target.kind === 'boundary'
          ? sheet.boundaries
          : sheet.relationships
    return list.find((item) => item.id === target.id) ?? null
  }, [selectedOverlay, sheet])

  const [labelDraft, setLabelDraft] = useState('')
  const [notesDraft, setNotesDraft] = useState('')
  const [hrefDraft, setHrefDraft] = useState('')
  const [formulaDraft, setFormulaDraft] = useState('')
  const [codeDraft, setCodeDraft] = useState('')
  // 新建代码块的语言初始值：来自「默认样式」面板的设置（null = 纯文本）
  const [codeLangDraft, setCodeLangDraft] = useState(() => defaultCodeLanguage())
  const codeAreaRef = useRef<HTMLTextAreaElement | null>(null)
  const formulaAreaRef = useRef<HTMLTextAreaElement | null>(null)

  // Alt+C 的落点：面板一打开（或已打开时收到信号）就把焦点交给代码输入框
  useEffect(() => {
    if (codeFocusTick > 0) codeAreaRef.current?.focus()
  }, [codeFocusTick])

  // 快捷栏「公式」的落点：同理聚焦公式输入框
  useEffect(() => {
    if (formulaFocusTick > 0) formulaAreaRef.current?.focus()
  }, [formulaFocusTick])

  // 只在「切换所选节点」时同步草稿，输入过程中绝不覆盖用户正在敲的内容
  useEffect(() => {
    setLabelDraft('')
    setNotesDraft(topic?.notes ?? '')
    setHrefDraft(topic?.href ?? '')
    setFormulaDraft(topic?.formula ?? '')
    setCodeDraft(topic?.code?.text ?? '')
    // 节点已有代码块用它自己的语言；没有（准备新建）时用默认语言
    setCodeLangDraft(topic?.code?.language || defaultCodeLanguage())
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id])

  const header = (
    <div className="side-panel__header">
      <span>节点属性</span>
      <button type="button" className="tool-btn" title="关闭" onMouseDown={(e) => e.preventDefault()} onClick={onClose}>
        <X size={16} />
      </button>
    </div>
  )

  /**
   * 画布级元素的属性：文字 + 字体（字号/加粗/斜体/颜色）+ 删除。
   *
   * 概要此前「文字删空就只剩一个框、点不到也改不了」——现在它和主题一样可选中、可改样式，
   * 文字清空后依然保留点击区（画布上有占位提示）。
   */
  if (selectedOverlay && overlayItem) {
    const kind: OverlayKind = selectedOverlay.kind
    const label = kind === 'summary' ? '概要' : kind === 'boundary' ? '边界' : '关系线'
    const styleText = readOverlayTextStyle(
      overlayItem.style,
      kind === 'summary' ? { fontSize: 13, bold: true } : { fontSize: 12, bold: true }
    )
    const setTitle =
      kind === 'summary' ? setSummaryTitle : kind === 'boundary' ? setBoundaryTitle : setRelationshipTitle
    const remove = kind === 'summary' ? removeSummary : kind === 'boundary' ? removeBoundary : removeRelationship

    return (
      <div className="side-panel">
        {header}
        <div className="side-panel__body">
          <div className="side-panel__empty">
            已选中画布上的「{label}」：文字与字体都能改，和主题一样支持撤销。
          </div>

          <div className="side-panel__title">{label}文字</div>
          <textarea
            key={`${overlayItem.id}-${overlayItem.title ?? ''}`}
            className="input input--area overlay-row__multi"
            rows={3}
            defaultValue={overlayItem.title ?? ''}
            placeholder="输入文字（Enter 换行；清空后画布上仍留有可点击的占位）"
            onBlur={(event) => setTitle(overlayItem.id, event.currentTarget.value)}
          />

          <div className="side-panel__title">字体</div>
          <div className="side-panel__row">
            <select
              className="select"
              value={styleText.fontSize}
              onChange={(event) =>
                setOverlayStyle(kind, overlayItem.id, { fontSize: Number(event.target.value) })
              }
            >
              {OVERLAY_FONT_SIZES.map((size) => (
                <option key={size} value={size}>
                  {size}
                </option>
              ))}
            </select>
            <button
              type="button"
              className={styleText.bold ? 'fmt-btn fmt-btn--active' : 'fmt-btn'}
              title="加粗"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => setOverlayStyle(kind, overlayItem.id, { bold: !styleText.bold })}
            >
              <Bold size={15} />
            </button>
            <button
              type="button"
              className={styleText.italic ? 'fmt-btn fmt-btn--active' : 'fmt-btn'}
              title="斜体"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => setOverlayStyle(kind, overlayItem.id, { italic: !styleText.italic })}
            >
              <Italic size={15} />
            </button>
            <button
              type="button"
              className="fmt-btn"
              title="恢复默认字体"
              onMouseDown={(e) => e.preventDefault()}
              /* 传 0 / false / 空串＝把对应属性删掉，恢复元素本身的默认外观 */
              onClick={() =>
                setOverlayStyle(kind, overlayItem.id, {
                  fontSize: 0,
                  bold: false,
                  italic: false,
                  color: ''
                })
              }
            >
              <Eraser size={14} />
            </button>
          </div>
          <div className="side-panel__row">
            <span className="side-panel__hint">颜色</span>
            {OVERLAY_COLORS.map((color) => (
              <button
                key={color}
                type="button"
                className={styleText.color === color ? 'color-dot color-dot--active' : 'color-dot'}
                style={{ background: color }}
                title={color}
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => setOverlayStyle(kind, overlayItem.id, { color })}
              />
            ))}
          </div>

          <div className="side-panel__hint">
            双击画布上的文字也能直接编辑；选中后按 Delete 删除这个{label}。
          </div>
          <div className="side-panel__row">
            <button
              type="button"
              className="btn"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => {
                remove(overlayItem.id)
                useEditor.getState().clearOverlaySelection()
              }}
            >
              <X size={14} /> 删除{label}
            </button>
          </div>
        </div>
      </div>
    )
  }

  if (!topic || !id) {
    return (
      <div className="side-panel">
        {header}
        <div className="side-panel__body">
          <div className="side-panel__empty">
            请先在画布上选中一个主题，再设置它的标记图标、标签、备注与超链接。
          </div>
        </div>
      </div>
    )
  }

  const topicId = id

  const commitNotes = (): void => {
    if ((topic.notes ?? '') !== notesDraft) setNotes(topicId, notesDraft)
  }

  const commitHref = (): void => {
    if ((topic.href ?? '') !== hrefDraft) setHref(topicId, hrefDraft)
  }

  const handleAddLabel = (): void => {
    const text = labelDraft.trim()
    if (text.length === 0) return
    addLabel(topicId, text)
    setLabelDraft('')
  }

  const openHref = async (): Promise<void> => {
    if (!topic.href) return
    try {
      const ok = await window.api.openExternal(topic.href)
      if (!ok) onNotify('这个链接不是 http/https/mailto，无法用系统程序打开')
    } catch (error) {
      onNotify(`打开链接失败：${(error as Error).message}`)
    }
  }

  const commitFormula = (): void => {
    // 支持 Markdown / LaTeX 各种数学写法：$x^2$、$$x^2$$、\(x^2\)、\[x^2\] 都剥成纯 LaTeX
    const next = normalizeFormulaInput(formulaDraft)
    if (next !== formulaDraft) setFormulaDraft(next)
    if ((topic.formula ?? '') !== next) setFormula(topicId, next)
  }

  const commitCode = (): void => {
    const text = codeDraft.replace(/\s+$/, '')
    const language = codeLangDraft
    if ((topic.code?.text ?? '') === text && (topic.code?.language ?? 'text') === language) return
    setCode(topicId, text.length === 0 && language === 'text' ? null : { language, text })
  }

  const insertImage = async (): Promise<void> => {
    try {
      const picked = await window.api.pickImage(activeDocId())
      if (!picked) return
      setImage(topicId, { path: picked.path, width: picked.width, height: picked.height })
      onNotify(
        picked.width > 0
          ? `已插入图片 ${picked.name}（${picked.width}×${picked.height}）`
          : `已插入图片 ${picked.name}（未取到像素尺寸，按默认大小显示）`
      )
    } catch (error) {
      onNotify(`插入图片失败：${(error as Error).message}`)
    }
  }

  const attachFile = async (): Promise<void> => {
    try {
      const picked = await window.api.pickAttachment(activeDocId())
      if (!picked) return
      addAttachment(topicId, picked)
      onNotify(`已添加附件 ${picked.name}，保存时会打包进 .xmind`)
    } catch (error) {
      onNotify(`添加附件失败：${(error as Error).message}`)
    }
  }

  const openAttachment = async (path: string, name: string): Promise<void> => {
    try {
      const ok = await window.api.openAttachment(path, name)
      if (!ok) onNotify('打不开这个附件：它可能只是文件里的记录，内容已经丢失')
    } catch (error) {
      onNotify(`打开附件失败：${(error as Error).message}`)
    }
  }

  const exportAttachment = async (path: string, name: string): Promise<void> => {
    try {
      const ok = await window.api.saveAttachmentAs(path, name)
      if (ok) onNotify('附件已导出')
    } catch (error) {
      onNotify(`导出附件失败：${(error as Error).message}`)
    }
  }

  /**
   * 画布元素的一行。
   * 标题用「非受控输入 + 失焦提交」：既不会被中文输入法打断，
   * 也不会每敲一个字就写一条撤销记录。
   * key 里带上已保存的标题，撤销/重做后能自动同步显示。
   */
  const overlayRow = (
    kind: string,
    items: Array<{ id: string; title: string | undefined }>,
    setTitle: (id: string, title: string) => void,
    remove: (id: string) => void,
    multiline = false
  ): ReactElement[] =>
    items.map((item) => (
      <div key={`${kind}-${item.id}`} className="overlay-row">
        <span className="overlay-row__tag">{kind}</span>
        {multiline ? (
          <textarea
            key={`${item.id}-${item.title ?? ''}`}
            className="input input--mini overlay-row__multi"
            rows={2}
            defaultValue={item.title ?? ''}
            placeholder="标题（可留空，Enter 换行）"
            onBlur={(event) => setTitle(item.id, event.currentTarget.value)}
          />
        ) : (
          <input
            key={`${item.id}-${item.title ?? ''}`}
            className="input input--mini"
            defaultValue={item.title ?? ''}
            placeholder="标题（可留空）"
            onBlur={(event) => setTitle(item.id, event.currentTarget.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter') event.currentTarget.blur()
            }}
          />
        )}
        <button
          type="button"
          className="chip__del"
          title={`移除这条${kind}`}
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => remove(item.id)}
        >
          <X size={10} />
        </button>
      </div>
    ))

  return (
    <div className="side-panel">
      {header}

      <div className="side-panel__body">
        <div className="side-panel__title">当前主题</div>
        <div className="node-preview" title={topic.title}>
          {topic.title || '（空标题）'}
        </div>

        <div className="side-panel__title">标记图标</div>

        {/* 已添加的标记（包含文件里带来、本软件不认识的标记，这里可以移除） */}
        {topic.markers.length > 0 ? (
          <div className="chip-row">
            {topic.markers.map((marker) => (
              <span key={`on-${marker.markerId}`} className="chip">
                <MarkerIcon markerId={marker.markerId} size={14} />
                <span className="chip__text">{markerVisualOf(marker.markerId).label}</span>
                <button
                  type="button"
                  className="chip__del"
                  title="移除此标记"
                  onMouseDown={(e) => e.preventDefault()}
                  onClick={() => toggleMarker(topicId, marker.markerId)}
                >
                  <X size={10} />
                </button>
              </span>
            ))}
          </div>
        ) : (
          <div className="side-panel__hint">还没有标记。点击下面的图标即可添加。</div>
        )}

        {MARKER_GROUPS.map((group) => (
          <div key={group.title} className="marker-row">
            <span className="marker-row__label">{group.title}</span>
            <div className="marker-picker">
              {group.markers.map((markerId) => {
                const active = topic.markers.some((marker) => marker.markerId === markerId)
                return (
                  <button
                    key={markerId}
                    type="button"
                    className={active ? 'marker-btn marker-btn--active' : 'marker-btn'}
                    title={markerVisualOf(markerId).label}
                    onMouseDown={(e) => e.preventDefault()}
                    onClick={() => toggleMarker(topicId, markerId)}
                  >
                    <MarkerIcon markerId={markerId} />
                  </button>
                )
              })}
            </div>
          </div>
        ))}

        <div className="side-panel__title">标签</div>
        {topic.labels.length > 0 && (
          <div className="chip-row">
            {topic.labels.map((label) => (
              <span key={`label-${label}`} className="chip">
                <span className="chip__text">{label}</span>
                <button
                  type="button"
                  className="chip__del"
                  title="移除标签"
                  onMouseDown={(e) => e.preventDefault()}
                  onClick={() => removeLabel(topicId, label)}
                >
                  <X size={10} />
                </button>
              </span>
            ))}
          </div>
        )}
        <div className="side-panel__row">
          <input
            className="input"
            placeholder="输入标签后回车"
            value={labelDraft}
            onChange={(event) => setLabelDraft(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter') handleAddLabel()
            }}
          />
          <button type="button" className="btn btn--primary" onMouseDown={(e) => e.preventDefault()} onClick={handleAddLabel}>
            <Plus size={14} />
            添加
          </button>
        </div>

        <div className="side-panel__title">备注</div>
        <textarea
          className="input input--area"
          rows={5}
          placeholder="记录这个主题的详细说明（点别处或离开输入框时保存）"
